module.exports = [

  // ─── GROUP 1: HIGH-TRAFFIC GENERAL TOOLS ───────────────────────────────────

  { slug:'age-calculator', name:'Age Calculator', desc:'Calculate your exact age in years, months, days and weeks.', icon:'body', category:'General',
    fields:[{id:'dob',label:'Date of Birth',type:'date'}],
    logic:`var dob=new Date(document.getElementById('dob').value);if(!document.getElementById('dob').value){alert('Enter your date of birth');return;}var now=new Date();var y=now.getFullYear()-dob.getFullYear();var mo=now.getMonth()-dob.getMonth();var d=now.getDate()-dob.getDate();if(d<0){mo--;d+=new Date(now.getFullYear(),now.getMonth(),0).getDate();}if(mo<0){y--;mo+=12;}var td=Math.floor((now-dob)/86400000);var nextBd=new Date(now.getFullYear(),dob.getMonth(),dob.getDate());if(nextBd<=now)nextBd.setFullYear(now.getFullYear()+1);var daysLeft=Math.ceil((nextBd-now)/86400000);showResult('result',y+' years '+mo+'mo '+d+'d','Your Exact Age','You are '+y+' years, '+mo+' months, and '+d+' days old — about '+td.toLocaleString()+' total days ('+Math.round(td/7).toLocaleString()+' weeks). Next birthday in '+daysLeft+' days.','green');`,
    article:`<h2>Age Calculator — Calculate Your Exact Age</h2><p>Our Age Calculator gives you your precise age in years, months, days, and weeks. It also tells you how many days until your next birthday. This tool is useful for filling medical forms, legal documents, insurance applications, and simply satisfying your curiosity about exactly how long you have been alive.</p><h3>Why Exact Age Matters</h3><p>Medical dosage guidelines, vaccine schedules, developmental milestones, and pension calculations all rely on exact age. Knowing your age to the day can be important for financial planning, health screenings, and meeting age-based requirements for benefits and services.</p><h3>Fun Age Facts</h3><p>By age 30, you have lived roughly 10,957 days and your heart has beaten over one billion times. The average person takes about 700 million breaths in a lifetime. Use this calculator to discover fascinating statistics about your time on Earth.</p>`,
    faqs:[{q:'How is exact age calculated?',a:'By counting the full years, then remaining months, then remaining days between your birth date and today.'},{q:'What if my birthday is today?',a:'The calculator will show 0 days until your birthday and your new age.'},{q:'How many days old am I?',a:'The calculator shows your total day count. Most 30-year-olds are around 10,950–10,960 days old.'},{q:'Is age different across cultures?',a:'Korean age starts at 1 at birth and adds 1 each New Year. Our calculator uses the standard Western method.'},{q:'Can I use this for my pet?',a:'Yes! Animals have birth dates too. Enter your pet\'s birth date for their exact age.'}],
    related:['birthday-calculator','date-difference-calculator','biological-age-calculator']
  },

  { slug:'birthday-calculator', name:'Birthday Calculator', desc:'Find days until your next birthday and fun birthday stats.', icon:'body', category:'General',
    fields:[{id:'dob',label:'Date of Birth',type:'date'},{id:'name',label:'Your Name (optional)',type:'text',ph:'Your name'}],
    logic:`var dob=new Date(document.getElementById('dob').value);if(!document.getElementById('dob').value){alert('Enter date of birth');return;}var now=new Date();var name=document.getElementById('name').value||'You';var nextBd=new Date(now.getFullYear(),dob.getMonth(),dob.getDate());if(nextBd<=now)nextBd.setFullYear(now.getFullYear()+1);var days=Math.ceil((nextBd-now)/86400000);var age=nextBd.getFullYear()-dob.getFullYear();var day=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][nextBd.getDay()];var months=['January','February','March','April','May','June','July','August','September','October','November','December'];showResult('result',days+' days','Next Birthday',name+'\'s next birthday is in '+days+' days — on '+day+', '+months[nextBd.getMonth()]+' '+nextBd.getDate()+', '+nextBd.getFullYear()+'. Turning '+age+'! This birthday falls on a '+day+'.','green');`,
    article:`<h2>Birthday Calculator — How Many Days Until Your Birthday?</h2><p>Our Birthday Calculator tells you exactly how many days remain until your next birthday, what day of the week it falls on, and which age you will turn. Plan your celebration, set reminders, and discover fun facts about your special day.</p><h3>Birthday Trivia</h3><p>Statistically, you share your birthday with approximately 20 million other people worldwide. The most common birth months in the Northern Hemisphere are August and September (nine months after the holiday season). The least common birthday is February 29, which only occurs in leap years.</p><h3>Planning Your Celebration</h3><p>Knowing your exact birthday countdown helps you plan parties, book venues, or organize travel well in advance. Many people use birthday milestones like 30, 40, or 50 for reflection and goal-setting.</p>`,
    faqs:[{q:'What day of the week is my next birthday?',a:'The calculator shows the exact day of the week your next birthday falls on.'},{q:'How many people share my birthday?',a:'About 20 million people worldwide share any given birthday date.'},{q:'What is the rarest birthday?',a:'February 29 (leap day) is the rarest birthday, occurring only once every four years.'},{q:'Can I calculate a friend\'s birthday?',a:'Yes, enter any birth date to find out the days remaining to their next birthday.'},{q:'What if my birthday was yesterday?',a:'The calculator will count to the birthday one year from your birth date.'}],
    related:['age-calculator','date-difference-calculator','countdown-timer']
  },

  { slug:'date-difference-calculator', name:'Date Difference Calculator', desc:'Calculate the exact difference between two dates in days, weeks, months and years.', icon:'body', category:'General',
    fields:[{id:'date1',label:'Start Date',type:'date'},{id:'date2',label:'End Date',type:'date'}],
    logic:`var d1=new Date(document.getElementById('date1').value);var d2=new Date(document.getElementById('date2').value);if(!document.getElementById('date1').value||!document.getElementById('date2').value){alert('Enter both dates');return;}if(d2<d1){var tmp=d1;d1=d2;d2=tmp;}var ms=d2-d1;var days=Math.floor(ms/86400000);var weeks=Math.floor(days/7);var months=Math.floor(days/30.44);var years=Math.floor(days/365.25);var remDays=days%7;showResult('result',days+' days','Date Difference','Between your two dates: '+years+' years, '+months+' total months, '+weeks+' weeks ('+remDays+' extra days). Exact days: '+days.toLocaleString()+'. Business days (approx): '+Math.round(days*5/7).toLocaleString()+'.','green');`,
    article:`<h2>Date Difference Calculator</h2><p>The Date Difference Calculator finds the exact number of days, weeks, months, and years between any two dates. This tool is invaluable for project planning, calculating contract durations, tracking milestones, and understanding time spans in your personal or professional life.</p><h3>Common Uses</h3><p>Calculate how long you have been at your job, how many days until a deadline, the duration of a pregnancy, the age of a business, or the time between historical events. The tool also estimates business days for work-related planning.</p><h3>Understanding Date Math</h3><p>Because months have different numbers of days (28 to 31), and years can be leap years, calculating exact differences requires careful mathematics. This calculator handles all edge cases automatically.</p>`,
    faqs:[{q:'How many days between two dates?',a:'Enter both dates and the calculator shows the exact day count, including the calculation method.'},{q:'Does it count business days?',a:'Yes, the calculator provides an estimate of business days (weekdays) between the two dates.'},{q:'Can I use past and future dates?',a:'Yes, you can enter any dates — past, present, or future — and the calculator will find the difference.'},{q:'How do I calculate months between dates?',a:'The calculator divides total days by 30.44 (the average month length) for an accurate month count.'},{q:'Is the end date included in the count?',a:'The calculator counts the days from start to end, not including the start date itself.'}],
    related:['age-calculator','birthday-calculator','countdown-timer']
  },

  { slug:'percentage-calculator', name:'Percentage Calculator', desc:'Calculate percentages, percent change, and what percentage one number is of another.', icon:'body', category:'General',
    fields:[{id:'mode',label:'Calculation Type',type:'select',options:['What is X% of Y?','X is what % of Y?','% Change from X to Y','Add X% to Y','Subtract X% from Y']},{id:'val1',label:'First Value (X)',type:'number',ph:'25'},{id:'val2',label:'Second Value (Y)',type:'number',ph:'200'}],
    logic:`var mode=document.getElementById('mode').value;var x=parseFloat(document.getElementById('val1').value);var y=parseFloat(document.getElementById('val2').value);if(isNaN(x)||isNaN(y)){alert('Enter both values');return;}var res,label,info;if(mode==='What is X% of Y?'){res=(x/100*y).toFixed(2);label=x+'% of '+y;info=x+'% of '+y+' equals '+res+'. Example: a '+x+'% discount on $'+y+' saves you $'+res+'.';}else if(mode==='X is what % of Y?'){res=(x/y*100).toFixed(2);label='Percentage Result';info=x+' is '+res+'% of '+y+'. To verify: '+y+' x '+res+'% = '+x+'.';}else if(mode==='% Change from X to Y'){var ch=((y-x)/Math.abs(x)*100).toFixed(2);res=ch+'%';label=ch>0?'Increase':'Decrease';info='From '+x+' to '+y+' is a '+(ch>0?'+'+ ch:''+ch)+'% change. Difference: '+(y-x).toFixed(2)+'.';}else if(mode==='Add X% to Y'){res=(y*(1+x/100)).toFixed(2);label='Result After Adding '+x+'%';info=y+' + '+x+'% = '+res+'. Added amount: '+(y*x/100).toFixed(2)+'.';}else{res=(y*(1-x/100)).toFixed(2);label='Result After Subtracting '+x+'%';info=y+' - '+x+'% = '+res+'. Subtracted amount: '+(y*x/100).toFixed(2)+'.';}showResult('result',res,label,info,'green');`,
    article:`<h2>Percentage Calculator — All Types in One Tool</h2><p>Percentages are used everywhere — from calculating discounts and taxes to understanding statistics and tracking progress. Our Percentage Calculator handles five common percentage calculations in one simple tool. No need to remember formulas; just select your calculation type and enter your numbers.</p><h3>Common Percentage Formulas</h3><p>The basic percentage formula is: Part / Whole × 100 = Percentage. For percent change: (New Value − Old Value) / |Old Value| × 100. For finding a percentage of a number: Percentage × Number / 100. These formulas power all percentage-based calculations in finance, science, and everyday life.</p>`,
    faqs:[{q:'How do I calculate a percentage?',a:'Divide the part by the whole, then multiply by 100. Example: 25/200 × 100 = 12.5%.'},{q:'How do I find a percentage of a number?',a:'Multiply the number by the percentage, then divide by 100. Example: 20% of 150 = 150 × 20 / 100 = 30.'},{q:'How is percent change calculated?',a:'(New − Old) / |Old| × 100. A rise from 50 to 75 is a 50% increase.'},{q:'What is the difference between percentage and percentage points?',a:'Percentage expresses a ratio; percentage points measure the arithmetic difference between two percentages.'},{q:'How do I add a percentage to a number?',a:'Multiply the number by (1 + percentage/100). Adding 15% to 200: 200 × 1.15 = 230.'}],
    related:['loan-emi-calculator','tip-calculator','calorie-calculator']
  },

  { slug:'loan-emi-calculator', name:'Loan EMI Calculator', desc:'Calculate your monthly loan EMI payment, total interest, and repayment schedule.', icon:'body', category:'General',
    fields:[{id:'principal',label:'Loan Amount',type:'number',ph:'100000'},{id:'rate',label:'Annual Interest Rate (%)',type:'number',ph:'8.5'},{id:'tenure',label:'Loan Tenure (months)',type:'number',ph:'60'}],
    logic:`var P=parseFloat(document.getElementById('principal').value);var r=parseFloat(document.getElementById('rate').value)/100/12;var n=parseFloat(document.getElementById('tenure').value);if(!P||!r||!n){alert('Fill all fields');return;}var emi=P*r*Math.pow(1+r,n)/(Math.pow(1+r,n)-1);var total=emi*n;var interest=total-P;showResult('result','$'+Math.round(emi).toLocaleString()+'/mo','Monthly EMI Payment','Total repayment: $'+Math.round(total).toLocaleString()+' | Principal: $'+Math.round(P).toLocaleString()+' | Total interest: $'+Math.round(interest).toLocaleString()+' | Interest-to-principal ratio: '+Math.round(interest/P*100)+'%','green');`,
    article:`<h2>Loan EMI Calculator — Calculate Your Monthly Payments</h2><p>EMI stands for Equated Monthly Installment — the fixed payment you make every month to repay a loan. Our Loan EMI Calculator uses the standard amortization formula to instantly calculate your monthly payment, total repayment amount, and total interest cost for any loan.</p><h3>The EMI Formula</h3><p>EMI = P × r × (1+r)^n / ((1+r)^n − 1), where P is the principal, r is the monthly interest rate (annual rate ÷ 12), and n is the number of monthly payments. This formula ensures that each payment covers both interest and a portion of the principal, gradually reducing your debt to zero.</p><h3>How to Reduce Your EMI</h3><p>Increase your down payment to reduce the principal, negotiate a lower interest rate, or extend the loan tenure. However, extending tenure increases total interest paid. Use this calculator to compare different scenarios and find the optimal balance for your financial situation.</p>`,
    faqs:[{q:'What is EMI?',a:'EMI (Equated Monthly Installment) is the fixed amount you pay each month to repay a loan, covering both principal and interest.'},{q:'How is EMI calculated?',a:'EMI = P × r × (1+r)^n / ((1+r)^n − 1), where P is principal, r is monthly rate, and n is number of months.'},{q:'Does a longer tenure reduce EMI?',a:'Yes, but you pay more total interest. A longer tenure lowers monthly payments but increases total cost.'},{q:'What is the difference between reducing and flat interest rates?',a:'Reducing rate charges interest on the outstanding principal each month. Flat rate charges on the full original principal. Reducing rate is cheaper.'},{q:'How do I calculate my loan affordability?',a:'Ensure your EMI does not exceed 40% of your monthly income. Use our calculator to find a manageable EMI amount.'}],
    related:['percentage-calculator','tip-calculator','calorie-calculator']
  },

  { slug:'tip-calculator', name:'Tip Calculator', desc:'Calculate how much to tip and split the bill among friends.', icon:'food', category:'General',
    fields:[{id:'bill',label:'Bill Amount ($)',type:'number',ph:'75'},{id:'tip',label:'Tip Percentage (%)',type:'number',ph:'18'},{id:'people',label:'Number of People',type:'number',ph:'3'}],
    logic:`var bill=parseFloat(document.getElementById('bill').value);var tipPct=parseFloat(document.getElementById('tip').value);var people=parseFloat(document.getElementById('people').value)||1;if(!bill||isNaN(tipPct)){alert('Enter bill and tip %');return;}var tipAmt=bill*tipPct/100;var total=bill+tipAmt;var perPerson=total/people;showResult('result','$'+tipAmt.toFixed(2)+' tip','Bill Split','Total with '+tipPct+'% tip: $'+total.toFixed(2)+' | Per person ('+people+'): $'+perPerson.toFixed(2)+' | Tip per person: $'+(tipAmt/people).toFixed(2)+' | Just bill per person: $'+(bill/people).toFixed(2)+'','green');`,
    article:`<h2>Tip Calculator — Split the Bill Easily</h2><p>Our Tip Calculator makes it simple to calculate the right tip amount and split the total bill evenly among friends. Whether you are at a restaurant, spa, or hotel, knowing how much to tip and how to divide it fairly prevents awkward moments.</p><h3>Standard Tip Guidelines</h3><p>Restaurant service: 15-20% for good service, 25% for exceptional. Delivery: 10-15% with a minimum of $3-5. Haircut: 15-20%. Hotel housekeeping: $2-5 per night. Taxi/rideshare: 15-20%. These are guidelines — always consider the quality of service.</p>`,
    faqs:[{q:'How much should I tip at a restaurant?',a:'15% is standard for average service, 18-20% for good service, and 25%+ for exceptional service.'},{q:'Should I tip on the pre-tax or post-tax amount?',a:'Tipping on the pre-tax amount is technically correct, but most people tip on the total for simplicity.'},{q:'When should I not tip?',a:'In countries where tipping is not customary, or if service was genuinely unacceptable — though speaking to a manager is usually better.'},{q:'Do I tip differently for delivery?',a:'Yes, 10-15% is standard for delivery, with a minimum of $3-5 for short orders.'},{q:'How do I split the bill if people ordered different amounts?',a:'Use the individual amounts for fairness. Our calculator handles equal splits; for unequal splits, add individual tips separately.'}],
    related:['percentage-calculator','loan-emi-calculator','calorie-calculator']
  },

  { slug:'password-generator', name:'Password Generator', desc:'Generate a strong, secure random password instantly.', icon:'pill', category:'General',
    fields:[{id:'length',label:'Password Length',type:'number',ph:'16'},{id:'upper',label:'Include Uppercase',type:'select',options:['Yes','No']},{id:'nums',label:'Include Numbers',type:'select',options:['Yes','No']},{id:'sym',label:'Include Symbols',type:'select',options:['Yes','No']}],
    logic:`var len=Math.max(8,Math.min(64,parseInt(document.getElementById('length').value)||16));var upper=document.getElementById('upper').value==='Yes';var nums=document.getElementById('nums').value==='Yes';var sym=document.getElementById('sym').value==='Yes';var chars='abcdefghijklmnopqrstuvwxyz';if(upper)chars+='ABCDEFGHIJKLMNOPQRSTUVWXYZ';if(nums)chars+='0123456789';if(sym)chars+='!@#$%^&*_+-=?';var pw='';for(var i=0;i<len;i++)pw+=chars[Math.floor(Math.random()*chars.length)];var strength=len>=16&&upper&&nums&&sym?'Very Strong':len>=12&&(upper||nums||sym)?'Strong':len>=8?'Moderate':'Weak';showResult('result',pw,'Password (Strength: '+strength+')','Copy this password now and store it in a password manager. Never reuse passwords across multiple sites. Generate a new one each time for maximum security.','green');`,
    article:`<h2>Password Generator — Create Strong Secure Passwords</h2><p>A strong password is your first line of defense against unauthorized access. Our Password Generator creates cryptographically random passwords with your choice of length and character types. Longer passwords with mixed characters are exponentially harder to crack.</p><h3>What Makes a Strong Password?</h3><p>A strong password should be at least 12 characters long and include uppercase letters, lowercase letters, numbers, and symbols. Avoid dictionary words, personal information (birth dates, names), or simple patterns. A 16-character random password would take billions of years to crack with current technology.</p><h3>Password Security Best Practices</h3><p>Use a different password for every account. Store passwords in a reputable password manager like Bitwarden, 1Password, or Dashlane. Enable two-factor authentication wherever possible. Never share your passwords via email or text message.</p>`,
    faqs:[{q:'How long should a password be?',a:'At least 12 characters; 16 or more is recommended for important accounts like banking and email.'},{q:'Should I use symbols in my password?',a:'Yes. Adding symbols greatly increases password entropy, making it much harder to crack.'},{q:'Is it safe to use an online password generator?',a:'Our generator runs entirely in your browser — no password is ever sent to any server.'},{q:'How often should I change passwords?',a:'Change passwords immediately after a security breach. Regular changes are less critical if you use unique strong passwords.'},{q:'What is a password manager?',a:'A password manager securely stores all your unique passwords, so you only need to remember one master password.'}],
    related:['random-number-generator','text-counter','percentage-calculator']
  },

  { slug:'random-number-generator', name:'Random Number Generator', desc:'Generate random numbers within any range, including multiple numbers at once.', icon:'body', category:'General',
    fields:[{id:'min',label:'Minimum Value',type:'number',ph:'1'},{id:'max',label:'Maximum Value',type:'number',ph:'100'},{id:'count',label:'How Many Numbers',type:'number',ph:'1'}],
    logic:`var mn=parseInt(document.getElementById('min').value)||1;var mx=parseInt(document.getElementById('max').value)||100;var cnt=Math.max(1,Math.min(20,parseInt(document.getElementById('count').value)||1));if(mn>mx){alert('Minimum must be less than maximum');return;}var nums=[];for(var i=0;i<cnt;i++)nums.push(Math.floor(Math.random()*(mx-mn+1))+mn);showResult('result',nums.join(', '),'Random Numbers Generated','Generated '+cnt+' random number'+(cnt>1?'s':'')+' between '+mn+' and '+mx+'. Range size: '+(mx-mn+1)+' possible values. Click Generate again for new numbers.','green');`,
    article:`<h2>Random Number Generator</h2><p>Our Random Number Generator produces truly random integers within any range you specify. Generate a single number or up to 20 numbers at once. This tool is useful for games, lotteries, statistical sampling, classroom activities, and anywhere you need unbiased random selection.</p><h3>True vs Pseudo-Random Numbers</h3><p>Computer-generated random numbers are technically "pseudo-random" — produced by mathematical algorithms that appear statistically random. Our generator uses JavaScript's Math.random(), which is suitable for games, education, and casual use but not for cryptographic security applications.</p>`,
    faqs:[{q:'Are the numbers truly random?',a:'They are pseudo-random, generated by a mathematical algorithm. This is suitable for most practical uses but not cryptographic security.'},{q:'Can I generate lottery numbers?',a:'Yes! Set the range to match your lottery (e.g., 1 to 49) and generate 6 numbers.'},{q:'How many numbers can I generate at once?',a:'Up to 20 numbers per generation with our calculator.'},{q:'Can numbers repeat?',a:'Yes, the generator may produce duplicate numbers. This represents true independent randomness.'},{q:'Is this the same as dice rolling?',a:'A 1-6 range with 1 number is equivalent to rolling one die.'}],
    related:['percentage-calculator','password-generator','text-counter']
  },

  { slug:'text-counter', name:'Text Counter & Word Count', desc:'Count words, characters, sentences, and reading time in any text.', icon:'brain', category:'General',
    fields:[{id:'text',label:'Paste or Type Your Text',type:'text',ph:'Enter your text here...'}],
    logic:`var t=document.getElementById('text').value;if(!t.trim()){alert('Enter some text');return;}var words=t.trim()?t.trim().split(/\\s+/).length:0;var chars=t.length;var charsNS=t.replace(/\\s/g,'').length;var sentences=t.split(/[.!?]+/).filter(function(s){return s.trim().length>0;}).length;var paras=t.split(/\\n+/).filter(function(p){return p.trim().length>0;}).length;var readMin=Math.ceil(words/200);showResult('result',words+' words','Text Statistics','Characters: '+chars+' (without spaces: '+charsNS+') | Sentences: '+sentences+' | Paragraphs: '+paras+' | Reading time: ~'+readMin+' min (at 200 wpm)','green');`,
    article:`<h2>Word Counter & Text Statistics Tool</h2><p>Our Text Counter instantly analyzes any text and provides comprehensive statistics: word count, character count (with and without spaces), sentence count, paragraph count, and estimated reading time. This tool is invaluable for writers, students, bloggers, social media managers, and anyone working with text.</p><h3>Why Word Count Matters</h3><p>Academic essays have word limits. SEO articles need minimum word counts. Social media posts have character limits. Resumes should be concise. Knowing your exact word and character count helps you meet requirements and communicate more effectively.</p>`,
    faqs:[{q:'How is reading time calculated?',a:'Based on the average adult reading speed of about 200 words per minute.'},{q:'Does it count words in multiple languages?',a:'Yes, it counts any space-separated words regardless of language.'},{q:'What counts as a sentence?',a:'Text ending in a period, exclamation mark, or question mark.'},{q:'Is there a text length limit?',a:'The tool works with texts of any reasonable length; very large texts may slow the browser.'},{q:'Can I use this for social media character limits?',a:'Yes. Twitter allows 280 characters, Instagram captions 2,200, and LinkedIn posts 3,000.'}],
    related:['password-generator','random-number-generator','percentage-calculator']
  },

  { slug:'countdown-timer', name:'Countdown Timer', desc:'Set a countdown timer for any duration — live real-time countdown in your browser.', icon:'sleep', category:'General',
    fields:[{id:'hours',label:'Hours',type:'number',ph:'0'},{id:'minutes',label:'Minutes',type:'number',ph:'25'},{id:'seconds',label:'Seconds',type:'number',ph:'0'}],
    logic:`(function(){var h=parseInt(document.getElementById('hours').value)||0;var m=parseInt(document.getElementById('minutes').value)||0;var s=parseInt(document.getElementById('seconds').value)||0;var total=h*3600+m*60+s;if(!total){alert('Enter a time duration');return;}var end=Date.now()+total*1000;var rb=document.getElementById('result');rb.style.display='block';rb.querySelector('.result-label').textContent='Countdown Running';clearInterval(window._cdTimer);window._cdTimer=setInterval(function(){var rem=Math.max(0,Math.floor((end-Date.now())/1000));var rh=Math.floor(rem/3600);var rm=Math.floor((rem%3600)/60);var rs=rem%60;rb.querySelector('.result-value').textContent=(rh?rh+'h ':'')+rm+'m '+rs+'s';rb.querySelector('.result-suggestion').textContent='Timer running — stay focused and make the most of your time!';if(rem<=0){clearInterval(window._cdTimer);rb.querySelector('.result-label').textContent='Time Is Up!';rb.querySelector('.result-value').textContent='DONE';rb.querySelector('.result-suggestion').textContent='Your countdown has finished! Great work.';}},1000);})()`,
    article:`<h2>Countdown Timer — Live Countdown in Your Browser</h2><p>Our Countdown Timer lets you set any duration in hours, minutes, and seconds and counts down in real time right in your browser. Use it for focused work sessions (Pomodoro technique), exercise intervals, cooking, studying, or any timed activity. No app download needed — it works instantly in any modern browser.</p><h3>The Pomodoro Technique</h3><p>The Pomodoro Technique uses 25-minute focused work sessions followed by 5-minute breaks. After four sessions, take a longer 15-20 minute break. Research shows this method reduces mental fatigue, improves focus, and increases productivity. Set our timer to 25 minutes to try it right now.</p>`,
    faqs:[{q:'Does the timer work if I switch browser tabs?',a:'Yes, the timer continues running in the background when you switch tabs.'},{q:'Will the timer make a sound when done?',a:'The visual display changes to "Time Is Up!" when your countdown finishes.'},{q:'How long a countdown can I set?',a:'You can set any duration in hours, minutes, and seconds — from seconds to many hours.'},{q:'What is the Pomodoro Technique?',a:'25 minutes of focused work followed by a 5-minute break. Four sessions then earn a longer 15-20 minute break.'},{q:'Can I reset the timer?',a:'Simply click the button again with your desired time to start a fresh countdown.'}],
    related:['birthday-calculator','date-difference-calculator','age-calculator']
  },

  // ─── GROUP 2: ADVANCED HEALTH CALCULATORS ──────────────────────────────────

  { slug:'heart-age-calculator', name:'Heart Age Calculator', desc:'Estimate your cardiovascular heart age based on key risk factors.', icon:'heart', category:'Heart Health',
    fields:[{id:'age',label:'Actual Age',type:'number',ph:'45'},{id:'gender',label:'Gender',type:'select',options:['Male','Female']},{id:'smoker',label:'Current Smoker?',type:'select',options:['No','Yes']},{id:'bp',label:'Systolic Blood Pressure (mmHg)',type:'number',ph:'120'},{id:'chol',label:'Total Cholesterol (mg/dL)',type:'number',ph:'190'},{id:'diabetic',label:'Diabetic?',type:'select',options:['No','Yes']},{id:'exercise',label:'Exercise (days/week)',type:'number',ph:'3'}],
    logic:`var age=parseFloat(document.getElementById('age').value);var g=document.getElementById('gender').value;var smoker=document.getElementById('smoker').value==='Yes';var bp=parseFloat(document.getElementById('bp').value)||120;var chol=parseFloat(document.getElementById('chol').value)||190;var diab=document.getElementById('diabetic').value==='Yes';var ex=parseFloat(document.getElementById('exercise').value)||0;if(!age){alert('Enter your age');return;}var heartAge=age;if(smoker)heartAge+=8;if(bp>140)heartAge+=6;else if(bp>130)heartAge+=3;if(chol>240)heartAge+=5;else if(chol>200)heartAge+=2;if(diab)heartAge+=4;if(g==='Male')heartAge+=2;if(ex>=4)heartAge-=4;else if(ex>=2)heartAge-=2;heartAge=Math.round(heartAge);var diff=heartAge-age;var c=diff>5?'red':diff>0?'yellow':'green';showResult('result',heartAge+' years','Estimated Heart Age',diff>0?'Your heart is functioning like someone '+diff+' years older. Focus on blood pressure control, quitting smoking, and regular exercise to reduce cardiovascular risk.':diff<0?'Your heart is in great shape — performing like someone '+(Math.abs(diff))+' years younger! Keep up your healthy lifestyle.':'Your heart age matches your actual age. Maintain your current healthy habits.','green');`,
    article:`<h2>Heart Age Calculator — Know Your Cardiovascular Age</h2><p>Your heart age may be older or younger than your actual age depending on your lifestyle and health factors. The Heart Age Calculator estimates cardiovascular age based on key risk factors including blood pressure, cholesterol, smoking status, diabetes, and physical activity. Understanding your heart age can be a powerful motivator for lifestyle change.</p><h3>Key Risk Factors</h3><p>The major modifiable risk factors for premature heart aging include high blood pressure (the single biggest risk factor), smoking, high cholesterol, physical inactivity, and diabetes. Addressing even one of these factors can meaningfully reduce your cardiovascular risk and lower your heart age.</p>`,
    faqs:[{q:'What is heart age?',a:'Heart age estimates how old your cardiovascular system functions compared to your actual age, based on risk factors.'},{q:'Can I reverse my heart age?',a:'Yes. Quitting smoking, exercising regularly, controlling blood pressure and cholesterol can reduce your heart age.'},{q:'How accurate is this calculator?',a:'It provides a risk-based estimate. A clinical cardiovascular risk assessment with your doctor is more precise.'},{q:'What blood pressure is healthy?',a:'Normal is below 120/80 mmHg. Elevated is 120-129. Stage 1 hypertension starts at 130 mmHg systolic.'},{q:'How much does smoking affect heart age?',a:'Smoking can add 8-10 years to your heart age and doubles the risk of heart disease.'}],
    related:['blood-pressure-checker','cholesterol-risk-calculator','heart-rate-calculator','biological-age-calculator']
  },

  { slug:'metabolic-age-calculator', name:'Metabolic Age Calculator', desc:'Estimate your metabolic age based on BMR compared to average values for your gender.', icon:'body', category:'Body Metrics',
    fields:[{id:'age',label:'Actual Age',type:'number',ph:'35'},{id:'weight',label:'Weight (kg)',type:'number',ph:'75'},{id:'height',label:'Height (cm)',type:'number',ph:'170'},{id:'gender',label:'Gender',type:'select',options:['Male','Female']},{id:'muscle',label:'Muscle Build',type:'select',options:['Average','Lean/Athletic','Bulky/Heavy']}],
    logic:`var age=parseFloat(document.getElementById('age').value);var w=parseFloat(document.getElementById('weight').value);var h=parseFloat(document.getElementById('height').value);var g=document.getElementById('gender').value;var muscle=document.getElementById('muscle').value;if(!age||!w||!h){alert('Fill all fields');return;}var bmr=g==='Male'?10*w+6.25*h-5*age+5:10*w+6.25*h-5*age-161;if(muscle==='Lean/Athletic')bmr+=150;if(muscle==='Bulky/Heavy')bmr-=80;var avgBmr;if(g==='Male'){avgBmr=age<30?1950:age<40?1870:age<50?1800:age<60?1720:1640;}else{avgBmr=age<30?1550:age<40?1490:age<50?1440:age<60?1370:1310;}var metAge=Math.round(age*(avgBmr/bmr));var diff=metAge-age;var c=diff>8?'red':diff>3?'yellow':'green';showResult('result',metAge+' years','Estimated Metabolic Age',diff>0?'Your metabolic age is '+diff+' years older than actual. Increase muscle mass through strength training and optimize your diet to boost your BMR.':diff<0?'Excellent! Your metabolism runs '+(Math.abs(diff))+' years younger than average. Your fitness and muscle mass are working in your favor.':'Your metabolic age closely matches your actual age.',c);`,
    article:`<h2>Metabolic Age Calculator</h2><p>Metabolic age compares your Basal Metabolic Rate (BMR) to the average BMR for people your age and gender. If your BMR is higher than average, your metabolic age is younger than your actual age — meaning you burn more calories at rest. A lower BMR suggests your metabolism is "older" than your years.</p><h3>Why Metabolic Age Matters</h3><p>A younger metabolic age makes weight management easier and is associated with better energy levels, more efficient nutrient utilization, and generally better health outcomes. The primary driver of a young metabolic age is muscle mass — lean muscle tissue burns significantly more calories than fat at rest.</p>`,
    faqs:[{q:'What is metabolic age?',a:'Metabolic age compares your BMR to average BMR for people your age — a lower metabolic age means a faster metabolism.'},{q:'How can I lower my metabolic age?',a:'Build muscle through resistance training, eat adequate protein, stay active, and get quality sleep.'},{q:'Is a low metabolic age always good?',a:'A lower metabolic age (younger metabolism) is generally desirable as it means higher calorie burn at rest.'},{q:'How does muscle affect metabolic age?',a:'Muscle burns 3x more calories than fat at rest. More muscle = higher BMR = younger metabolic age.'},{q:'Does age always worsen metabolism?',a:'Without intervention, BMR declines ~2% per decade. But regular strength training can maintain a youthful metabolism.'}],
    related:['bmr-calculator','tdee-calculator','body-fat-calculator','biological-age-calculator']
  },

  { slug:'homa-ir-calculator', name:'HOMA-IR Calculator', desc:'Calculate your HOMA-IR score to estimate insulin resistance from fasting glucose and insulin levels.', icon:'pill', category:'Health Risk',
    fields:[{id:'glucose',label:'Fasting Blood Glucose (mg/dL)',type:'number',ph:'95'},{id:'insulin',label:'Fasting Insulin (μIU/mL)',type:'number',ph:'8'}],
    logic:`var glu=parseFloat(document.getElementById('glucose').value);var ins=parseFloat(document.getElementById('insulin').value);if(!glu||!ins){alert('Enter both values');return;}var gluMmol=glu/18;var homa=(gluMmol*ins)/22.5;homa=homa.toFixed(2);var c='green',l='Insulin Sensitive',s='Your HOMA-IR score suggests good insulin sensitivity. Maintain a healthy diet and regular exercise to preserve this.';if(homa>2.9){c='red';l='Insulin Resistant';s='Your HOMA-IR is elevated, suggesting significant insulin resistance. Consult your doctor to discuss lifestyle changes and possible testing for prediabetes or type 2 diabetes.';}else if(homa>1.9){c='yellow';l='Borderline Resistance';s='Your HOMA-IR suggests early insulin resistance. A low-glycemic diet, regular exercise, and weight management can help improve insulin sensitivity.';}showResult('result',homa,'HOMA-IR Score',s,c);`,
    article:`<h2>HOMA-IR Calculator — Measure Insulin Resistance</h2><p>HOMA-IR (Homeostatic Model Assessment of Insulin Resistance) is a validated clinical formula used to estimate insulin resistance from fasting blood glucose and fasting insulin levels. Insulin resistance is the root cause of type 2 diabetes, metabolic syndrome, PCOS, and many other modern health conditions.</p><h3>HOMA-IR Formula</h3><p>HOMA-IR = (Fasting Glucose in mmol/L × Fasting Insulin in μIU/mL) / 22.5. A score below 1.0 indicates excellent insulin sensitivity. Scores of 1.0-1.9 are considered normal, 2.0-2.9 borderline, and 3.0+ suggests significant insulin resistance.</p>`,
    faqs:[{q:'What is HOMA-IR?',a:'A mathematical formula estimating insulin resistance from fasting blood glucose and insulin levels.'},{q:'What is a normal HOMA-IR score?',a:'Below 1.0 is excellent. 1.0-1.9 is normal. Above 2.0 suggests developing insulin resistance.'},{q:'How do I get my fasting insulin tested?',a:'Ask your doctor to add fasting insulin to your routine blood work. It is not always included by default.'},{q:'Can HOMA-IR be improved?',a:'Yes. Low-carb/low-glycemic diet, intermittent fasting, exercise, and weight loss all improve HOMA-IR scores significantly.'},{q:'Is HOMA-IR related to diabetes?',a:'Yes. Elevated HOMA-IR is a strong predictor of prediabetes and type 2 diabetes risk.'}],
    related:['diabetes-risk-calculator','blood-pressure-checker','intermittent-fasting-calculator','bmi-calculator']
  },

  { slug:'visceral-fat-calculator', name:'Visceral Fat Estimator', desc:'Estimate your visceral fat level using waist circumference and BMI-based assessment.', icon:'body', category:'Body Metrics',
    fields:[{id:'waist',label:'Waist Circumference (cm)',type:'number',ph:'85'},{id:'height',label:'Height (cm)',type:'number',ph:'170'},{id:'weight',label:'Weight (kg)',type:'number',ph:'75'},{id:'age',label:'Age',type:'number',ph:'40'},{id:'gender',label:'Gender',type:'select',options:['Male','Female']}],
    logic:`var w=parseFloat(document.getElementById('waist').value);var h=parseFloat(document.getElementById('height').value);var wt=parseFloat(document.getElementById('weight').value);var age=parseFloat(document.getElementById('age').value);var g=document.getElementById('gender').value;if(!w||!h||!wt||!age){alert('Fill all fields');return;}var whr=w/h;var bmi=wt/Math.pow(h/100,2);var score=0;if(whr>0.5)score+=2;if(whr>0.6)score+=2;if(bmi>25)score+=1;if(bmi>30)score+=2;if(age>40)score+=1;if(age>55)score+=1;if(g==='Male')score+=1;var level=score<=2?'Low (Level 1-3)':score<=5?'Moderate (Level 4-7)':score<=7?'High (Level 8-12)':'Very High (Level 12+)';var c=score<=2?'green':score<=5?'yellow':'red';var waistThresh=g==='Male'?94:80;var threshNote=w>waistThresh?' Your waist is above the health threshold of '+waistThresh+'cm for '+g+'s.':' Your waist is within the recommended range.';showResult('result',level,'Visceral Fat Estimate','Waist-to-height ratio: '+whr.toFixed(2)+' (healthy target: under 0.50).'+threshNote+' Visceral fat is reduced most effectively through diet and aerobic exercise.',c);`,
    article:`<h2>Visceral Fat Estimator</h2><p>Visceral fat is the dangerous fat stored around your internal organs — liver, pancreas, and intestines. Unlike subcutaneous fat (under the skin), visceral fat is metabolically active and strongly linked to type 2 diabetes, heart disease, inflammation, and metabolic syndrome. Even people at normal weight can carry excess visceral fat.</p><h3>How to Estimate Visceral Fat</h3><p>Without a DEXA scan, waist circumference and waist-to-height ratio are the best proxy measures. A waist above 94cm in men or 80cm in women indicates elevated visceral fat risk. A waist-to-height ratio above 0.5 is a simple, universal red flag regardless of body size.</p>`,
    faqs:[{q:'What is visceral fat?',a:'Fat stored around internal organs in the abdominal cavity. It is more dangerous than subcutaneous (under-skin) fat.'},{q:'How do I reduce visceral fat?',a:'High-intensity aerobic exercise and a low-refined-carbohydrate diet are most effective for reducing visceral fat.'},{q:'Can I have high visceral fat at normal weight?',a:'Yes, this is called TOFI (Thin Outside, Fat Inside) or metabolically obese normal weight. Waist circumference reveals it.'},{q:'Is visceral fat worse than other fat?',a:'Yes. It releases inflammatory hormones and fatty acids that directly affect liver and metabolic function.'},{q:'How accurate is waist circumference for visceral fat?',a:'It is the best non-imaging proxy available. DEXA scan is more accurate but expensive and requires a clinical setting.'}],
    related:['body-fat-calculator','waist-to-hip-ratio','bmi-calculator','homa-ir-calculator']
  },

  { slug:'sodium-intake-calculator', name:'Sodium Intake Calculator', desc:'Calculate your recommended daily sodium intake and check if your current intake is safe.', icon:'food', category:'Nutrition',
    fields:[{id:'current',label:'Current Daily Sodium Intake (mg)',type:'number',ph:'2500'},{id:'condition',label:'Health Status',type:'select',options:['Healthy Adult','High Blood Pressure','Heart Disease','Kidney Disease','Age 51+']},{id:'exercise',label:'Exercise Level',type:'select',options:['Sedentary','Moderate (3-4 hrs/week)','Active (5+ hrs/week)']}],
    logic:`var curr=parseFloat(document.getElementById('current').value)||2500;var cond=document.getElementById('condition').value;var ex=document.getElementById('exercise').value;var rec=cond==='Healthy Adult'?2300:1500;if(ex==='Active (5+ hrs/week)')rec+=500;var diff=curr-rec;var c=curr<=rec?'green':curr<=rec*1.3?'yellow':'red';var l=curr<=rec?'Within Safe Range':curr<=rec*1.3?'Slightly Over':'Significantly Over';var s='Recommended daily limit: '+rec+' mg. Current intake: '+curr+' mg. '+(diff>0?'You are consuming '+diff+' mg more than recommended. Reduce processed foods, canned goods, and restaurant meals.':'You are '+Math.abs(diff)+' mg under the limit. Good job managing your sodium!');showResult('result',curr+' mg/day',l,s,c);`,
    article:`<h2>Sodium Intake Calculator</h2><p>Sodium is an essential mineral, but most people consume far too much — primarily from processed foods, restaurant meals, and packaged snacks. Excess sodium raises blood pressure, strains the kidneys, and increases cardiovascular risk. The American Heart Association recommends no more than 2,300 mg daily for healthy adults and ideally less than 1,500 mg for those with heart disease or high blood pressure.</p><h3>Hidden Sources of Sodium</h3><p>About 70% of sodium intake comes from packaged and restaurant foods, not the salt shaker. High-sodium culprits include bread (150-250mg per slice), canned soup (800-1500mg per serving), deli meat (500-700mg per serving), pizza (600-900mg per slice), and soy sauce (900mg per tablespoon).</p>`,
    faqs:[{q:'How much sodium should I eat per day?',a:'The FDA recommends less than 2,300 mg per day. Those with high blood pressure should aim for 1,500 mg or less.'},{q:'Does exercise affect sodium needs?',a:'Yes. Heavy sweating increases sodium loss. Athletes may need slightly more sodium to replace what is lost.'},{q:'What are the symptoms of too much sodium?',a:'Bloating, high blood pressure, increased thirst, and water retention are common signs of excess sodium.'},{q:'Can low sodium be dangerous?',a:'Yes, hyponatremia (low blood sodium) can occur from overhydration during endurance events. It causes nausea and confusion.'},{q:'How do I reduce sodium intake?',a:'Cook at home, read labels, choose low-sodium products, use herbs and spices instead of salt, and limit processed foods.'}],
    related:['blood-pressure-checker','water-intake-calculator','heart-age-calculator','cholesterol-risk-calculator']
  },

  { slug:'thyroid-risk-calculator', name:'Thyroid Risk Calculator', desc:'Assess your risk of thyroid dysfunction based on symptoms and risk factors.', icon:'pill', category:'Health Risk',
    fields:[{id:'gender',label:'Gender',type:'select',options:['Female','Male']},{id:'age',label:'Age',type:'number',ph:'35'},{id:'fatigue',label:'Fatigue/Low Energy (0-3)',type:'number',ph:'1'},{id:'weight',label:'Unexpected Weight Change (0-3)',type:'number',ph:'1'},{id:'cold',label:'Cold/Heat Sensitivity (0-3)',type:'number',ph:'1'},{id:'hair',label:'Hair Loss/Thinning (0-3)',type:'number',ph:'1'},{id:'mood',label:'Mood Changes/Depression (0-3)',type:'number',ph:'1'},{id:'family',label:'Family History of Thyroid?',type:'select',options:['No','Yes']}],
    logic:`var g=document.getElementById('gender').value;var age=parseFloat(document.getElementById('age').value)||30;var s1=parseFloat(document.getElementById('fatigue').value)||0;var s2=parseFloat(document.getElementById('weight').value)||0;var s3=parseFloat(document.getElementById('cold').value)||0;var s4=parseFloat(document.getElementById('hair').value)||0;var s5=parseFloat(document.getElementById('mood').value)||0;var fam=document.getElementById('family').value==='Yes';var score=s1+s2+s3+s4+s5;if(g==='Female')score+=2;if(age>50)score+=1;if(age>65)score+=1;if(fam)score+=3;var c='green',l='Low Risk',s='Your thyroid risk score is low. If you develop new symptoms, consult your doctor and ask for a TSH test.';if(score>=12){c='red';l='High Risk';s='Your score suggests significant thyroid symptom burden. Please consult your doctor and request a TSH (thyroid-stimulating hormone) blood test to rule out hypothyroidism or hyperthyroidism.';}else if(score>=7){c='yellow';l='Moderate Risk';s='Several thyroid-related symptoms and risk factors are present. Consider discussing thyroid function testing with your healthcare provider.';}showResult('result',score+'/20','Thyroid Risk Score',s,c);`,
    article:`<h2>Thyroid Risk Calculator</h2><p>The thyroid gland regulates metabolism, energy, body temperature, and dozens of other critical functions. Thyroid disorders are among the most common and frequently undiagnosed conditions — affecting an estimated 20 million Americans, with women 5-8 times more likely to be affected. Hypothyroidism (underactive thyroid) causes fatigue, weight gain, and depression. Hyperthyroidism (overactive thyroid) causes weight loss, anxiety, and rapid heartbeat.</p><h3>Key Thyroid Risk Factors</h3><p>Female gender, age over 50, family history of thyroid disease, previous thyroid issues, autoimmune conditions (like Hashimoto's or Graves' disease), and iodine deficiency all increase thyroid disorder risk. A simple TSH blood test can screen for most thyroid problems.</p>`,
    faqs:[{q:'What is the thyroid?',a:'A butterfly-shaped gland in your neck that produces hormones regulating metabolism, heart rate, body temperature, and energy.'},{q:'What is hypothyroidism?',a:'An underactive thyroid that produces too little hormone, causing fatigue, weight gain, cold sensitivity, and depression.'},{q:'What is hyperthyroidism?',a:'An overactive thyroid producing too much hormone, causing weight loss, anxiety, heat intolerance, and rapid heartbeat.'},{q:'How is thyroid function tested?',a:'A TSH (thyroid-stimulating hormone) blood test is the primary screening test. T3 and T4 levels provide additional information.'},{q:'Are thyroid disorders curable?',a:'Most are manageable with medication. Hypothyroidism is typically treated with levothyroxine; hyperthyroidism with antithyroid drugs, radioiodine, or surgery.'}],
    related:['blood-pressure-checker','stress-level-calculator','biological-age-calculator','depression-screening-calculator']
  },

  { slug:'pcos-risk-calculator', name:'PCOS Risk Calculator', desc:'Assess your risk for polycystic ovary syndrome (PCOS) based on key symptoms.', icon:'baby', category:"Women's Health",
    fields:[{id:'cycle',label:'Irregular Periods?',type:'select',options:['No','Yes - slightly irregular','Yes - very irregular or absent']},{id:'acne',label:'Acne or Oily Skin?',type:'select',options:['None','Mild','Severe']},{id:'hair',label:'Excess Facial/Body Hair?',type:'select',options:['No','Mild','Significant']},{id:'weight',label:'Difficulty Losing Weight?',type:'select',options:['No','Mild','Significant']},{id:'hairloss',label:'Scalp Hair Thinning?',type:'select',options:['No','Mild','Significant']},{id:'family',label:'Family History of PCOS?',type:'select',options:['No','Yes']}],
    logic:`var cyc={'No':0,'Yes - slightly irregular':2,'Yes - very irregular or absent':4}[document.getElementById('cycle').value]||0;var acne={'None':0,'Mild':1,'Severe':2}[document.getElementById('acne').value]||0;var hair={'No':0,'Mild':1,'Significant':3}[document.getElementById('hair').value]||0;var wt={'No':0,'Mild':1,'Significant':2}[document.getElementById('weight').value]||0;var hl={'No':0,'Mild':1,'Significant':2}[document.getElementById('hairloss').value]||0;var fam=document.getElementById('family').value==='Yes'?2:0;var score=cyc+acne+hair+wt+hl+fam;var c='green',l='Low Likelihood',s='Your symptom score is low. PCOS is unlikely based on your responses, but if you have concerns about your menstrual cycle or hormones, speak with your gynecologist.';if(score>=10){c='red';l='High Likelihood';s='Your symptoms strongly suggest possible PCOS. Please consult a gynecologist or endocrinologist. Diagnosis requires a physical exam, blood tests (testosterone, LH/FSH), and pelvic ultrasound.';}else if(score>=6){c='yellow';l='Moderate Likelihood';s='You have several PCOS-associated symptoms. Consider speaking with your doctor about hormonal evaluation. PCOS is treatable with lifestyle changes and, if needed, medication.';}showResult('result',score+'/15','PCOS Risk Score',s,c);`,
    article:`<h2>PCOS Risk Calculator</h2><p>Polycystic Ovary Syndrome (PCOS) affects approximately 1 in 10 women of reproductive age, making it the most common endocrine disorder in women. It is characterized by hormonal imbalance, irregular periods, excess androgens, and often multiple small cysts on the ovaries. Despite being common, PCOS is frequently underdiagnosed — up to 70% of women with PCOS have never been diagnosed.</p><h3>PCOS Symptoms to Watch For</h3><p>Key symptoms include irregular, infrequent, or absent periods; excess hair growth on the face, chest, or back (hirsutism); acne; weight gain particularly around the abdomen; difficulty losing weight; scalp hair thinning; and skin tags. Insulin resistance is present in 70% of PCOS cases regardless of weight.</p>`,
    faqs:[{q:'What is PCOS?',a:'Polycystic Ovary Syndrome is a hormonal disorder causing irregular periods, excess androgens, and sometimes ovarian cysts.'},{q:'Can I have PCOS without cysts?',a:'Yes. The name is misleading — you can have PCOS without ovarian cysts. Diagnosis is based on symptoms and hormone levels.'},{q:'Is PCOS curable?',a:'There is no cure, but symptoms are very manageable with lifestyle changes, diet, exercise, and medication if needed.'},{q:'Does PCOS affect fertility?',a:'PCOS is a leading cause of infertility due to irregular ovulation, but most women with PCOS can conceive with treatment.'},{q:'What diet helps PCOS?',a:'A low-glycemic, anti-inflammatory diet (Mediterranean-style) helps manage insulin resistance, which underlies most PCOS symptoms.'}],
    related:['pregnancy-due-date-calculator','ovulation-calculator','fertility-calculator','homa-ir-calculator']
  },

  { slug:'pregnancy-weight-gain-calculator', name:'Pregnancy Weight Gain Calculator', desc:'Calculate recommended weight gain during pregnancy based on your pre-pregnancy BMI.', icon:'baby', category:"Women's Health",
    fields:[{id:'weight',label:'Pre-Pregnancy Weight (kg)',type:'number',ph:'65'},{id:'height',label:'Height (cm)',type:'number',ph:'165'},{id:'twins',label:'Single or Multiple?',type:'select',options:['Single Baby','Twins','Triplets+']},{id:'week',label:'Current Week of Pregnancy',type:'number',ph:'20'}],
    logic:`var w=parseFloat(document.getElementById('weight').value);var h=parseFloat(document.getElementById('height').value)/100;var twins=document.getElementById('twins').value;var week=parseFloat(document.getElementById('week').value)||20;if(!w||!h){alert('Fill all fields');return;}var bmi=w/(h*h);var lo,hi,label;if(twins==='Single Baby'){if(bmi<18.5){lo=12.5;hi=18;label='Underweight';}else if(bmi<25){lo=11.5;hi=16;label='Normal Weight';}else if(bmi<30){lo=7;hi=11.5;label='Overweight';}else{lo=5;hi=9;label='Obese';}}else if(twins==='Twins'){lo=17;hi=25;label='Twin Pregnancy';}else{lo=20;hi=30;label='Triplets+';}var trimGain=(lo+hi)/2/40*week;showResult('result',lo+'-'+hi+' kg total','Recommended Weight Gain','Pre-pregnancy BMI: '+bmi.toFixed(1)+' ('+label+'). Total recommended gain: '+lo+'-'+hi+' kg over 40 weeks. By week '+week+', an expected gain of ~'+trimGain.toFixed(1)+' kg is typical. Always follow your OB-GYN guidance.','green');`,
    article:`<h2>Pregnancy Weight Gain Calculator</h2><p>Gaining the right amount of weight during pregnancy is essential for your health and your baby's development. Too little weight gain increases the risk of premature birth and low birth weight. Too much increases the risk of gestational diabetes, C-section, and postpartum weight retention. The recommended range depends on your pre-pregnancy BMI.</p><h3>Weight Gain by Trimester</h3><p>In the first trimester, most women gain 1-2 kg total. In the second trimester, gain should be about 0.5 kg per week. The third trimester follows a similar pace. These gains include the baby (3-4 kg at term), placenta (0.7 kg), amniotic fluid (0.8 kg), increased blood volume (1.5 kg), breast tissue (0.9 kg), uterus growth (1 kg), and fat stores (2-4 kg).</p>`,
    faqs:[{q:'How much weight should I gain during pregnancy?',a:'Normal BMI women: 11.5-16 kg. Underweight: 12.5-18 kg. Overweight: 7-11.5 kg. Obese: 5-9 kg total.'},{q:'Is it safe to lose weight while pregnant?',a:'Weight loss during pregnancy is not recommended. Focus on quality nutrition and gaining within your recommended range.'},{q:'Why do twins require more weight gain?',a:'Twin pregnancies have greater nutritional demands and the total fetal mass is nearly double, requiring 17-25 kg total gain.'},{q:'When does most pregnancy weight gain occur?',a:'Primarily in the second and third trimesters, when the baby grows most rapidly.'},{q:'How quickly should weight normalize after birth?',a:'The first 6-12 weeks postpartum see natural fluid loss of 4-6 kg. Full return to pre-pregnancy weight typically takes 6-12 months with healthy habits.'}],
    related:['pregnancy-due-date-calculator','ovulation-calculator','baby-weight-calculator','breastfeeding-calorie-calculator']
  },

  { slug:'breastfeeding-calorie-calculator', name:'Breastfeeding Calorie Calculator', desc:'Calculate extra calorie needs during breastfeeding to support milk production and maternal health.', icon:'baby', category:"Women's Health",
    fields:[{id:'weight',label:'Current Weight (kg)',type:'number',ph:'65'},{id:'height',label:'Height (cm)',type:'number',ph:'165'},{id:'age',label:'Age',type:'number',ph:'30'},{id:'activity',label:'Activity Level',type:'select',options:['Sedentary','Lightly Active','Moderately Active','Very Active']},{id:'stage',label:'Breastfeeding Stage',type:'select',options:['0-6 months (exclusive)','6-12 months (partial)','12+ months']}],
    logic:`var w=parseFloat(document.getElementById('weight').value);var h=parseFloat(document.getElementById('height').value);var a=parseFloat(document.getElementById('age').value);var act=document.getElementById('activity').value;var stage=document.getElementById('stage').value;if(!w||!h||!a){alert('Fill all fields');return;}var bmr=10*w+6.25*h-5*a-161;var mult={'Sedentary':1.2,'Lightly Active':1.375,'Moderately Active':1.55,'Very Active':1.725};var base=Math.round(bmr*(mult[act]||1.2));var extra=stage==='0-6 months (exclusive)'?500:stage==='6-12 months (partial)'?400:300;var total=base+extra;showResult('result',total+' kcal/day','Daily Calorie Need (Breastfeeding)','Base calories: '+base+' kcal | Breastfeeding extra: +'+extra+' kcal | Total: '+total+' kcal. Focus on nutrient-dense foods, stay hydrated (drink to thirst), and avoid strict dieting during this stage.','green');`,
    article:`<h2>Breastfeeding Calorie Calculator</h2><p>Breastfeeding requires significant extra energy. The average woman burns approximately 400-500 additional calories per day producing breast milk. Our calculator estimates your total calorie needs during breastfeeding to ensure both you and your baby get adequate nutrition.</p><h3>Nutrition During Breastfeeding</h3><p>Beyond calories, breastfeeding mothers need extra protein (25g more per day), calcium, vitamin D, omega-3 fatty acids, and iodine. These nutrients pass through breast milk to support your baby's growth and development. A prenatal vitamin continued through breastfeeding helps fill nutritional gaps.</p>`,
    faqs:[{q:'How many extra calories do I need while breastfeeding?',a:'Most guidelines recommend 400-500 additional calories per day during exclusive breastfeeding in the first 6 months.'},{q:'Can I diet while breastfeeding?',a:'Mild calorie reduction (no more than 300-500 below total needs) is generally safe after 6-8 weeks postpartum, but avoid crash dieting.'},{q:'What foods should I avoid while breastfeeding?',a:'Limit alcohol, caffeine (under 300mg/day), and certain fish high in mercury. Most foods are safe in moderation.'},{q:'Does breastfeeding help with postpartum weight loss?',a:'Yes, but not always immediately. Many women lose 0.5-1 kg per month while exclusively breastfeeding without restricting calories.'},{q:'How much water should I drink while breastfeeding?',a:'Aim for 3-3.5 liters of total fluid daily. Drink to thirst — your body regulates well, but staying hydrated is important.'}],
    related:['pregnancy-due-date-calculator','baby-weight-calculator','pregnancy-weight-gain-calculator','calorie-calculator']
  },

  { slug:'menopause-symptom-calculator', name:'Menopause Symptom Calculator', desc:'Score your menopause symptom severity and get personalized guidance.', icon:'baby', category:"Women's Health",
    fields:[{id:'age',label:'Age',type:'number',ph:'50'},{id:'hotflash',label:'Hot Flashes Frequency (0-3)',type:'number',ph:'2'},{id:'sleep',label:'Sleep Disruption (0-3)',type:'number',ph:'2'},{id:'mood',label:'Mood Changes (0-3)',type:'number',ph:'1'},{id:'vaginal',label:'Vaginal Dryness/Discomfort (0-3)',type:'number',ph:'1'},{id:'cognitive',label:'Brain Fog/Memory Issues (0-3)',type:'number',ph:'1'},{id:'period',label:'Menstrual Status',type:'select',options:['Regular periods','Irregular periods','No period 3-11 months','No period 12+ months']}],
    logic:`var age=parseFloat(document.getElementById('age').value)||50;var hf=parseFloat(document.getElementById('hotflash').value)||0;var sl=parseFloat(document.getElementById('sleep').value)||0;var mo=parseFloat(document.getElementById('mood').value)||0;var vg=parseFloat(document.getElementById('vaginal').value)||0;var cg=parseFloat(document.getElementById('cognitive').value)||0;var period=document.getElementById('period').value;var stage=period==='Regular periods'?'Premenopause':period==='Irregular periods'?'Perimenopause':period==='No period 3-11 months'?'Late Perimenopause':'Postmenopause';var score=hf+sl+mo+vg+cg;var c=score<=4?'green':score<=9?'yellow':'red';var l=score<=4?'Mild Symptoms':score<=9?'Moderate Symptoms':'Significant Symptoms';var s='Stage: '+stage+'. Symptom score: '+score+'/15. '+(score<=4?'Your symptoms are mild and manageable. Lifestyle adjustments like regular exercise, cooling clothing, and good sleep hygiene often suffice.':score<=9?'Your symptoms are moderate. Consider speaking with your doctor about options including lifestyle changes, hormone therapy (HRT), or non-hormonal medications.':'Your symptoms are significantly impacting quality of life. Please consult a menopause specialist to discuss evidence-based treatments including HRT and non-hormonal options.');showResult('result',score+'/15',l,s,c);`,
    article:`<h2>Menopause Symptom Calculator</h2><p>Menopause is a natural biological transition marking the end of reproductive years, officially defined as 12 consecutive months without a menstrual period. The average age at menopause is 51, though perimenopause (the transitional phase) can begin years earlier. Symptoms vary enormously — some women sail through with minimal discomfort, while others experience significant disruption to daily life.</p><h3>Most Common Menopause Symptoms</h3><p>Hot flashes and night sweats affect 75% of women. Sleep disturbances, mood changes, vaginal dryness, cognitive changes (brain fog), joint pain, weight gain around the abdomen, and changes in skin and hair texture are all common. Duration varies from months to over a decade.</p>`,
    faqs:[{q:'What is perimenopause?',a:'The transitional phase before menopause, typically beginning in the mid-40s, characterized by hormonal fluctuations and irregular periods.'},{q:'How long does menopause last?',a:'Menopause itself is a moment in time (12 months without a period). Perimenopause lasts 4-8 years; postmenopausal symptoms can persist for years.'},{q:'Is hormone replacement therapy (HRT) safe?',a:'For most healthy women under 60 starting within 10 years of menopause, HRT benefits outweigh risks. Discuss with your doctor.'},{q:'What natural remedies help menopause symptoms?',a:'Regular exercise, reduced alcohol and caffeine, cooling techniques, phytoestrogens (soy), black cohosh, and cognitive behavioral therapy all have evidence.'},{q:'Can menopause cause weight gain?',a:'Yes. Estrogen decline shifts fat storage to the abdomen. Maintaining muscle through strength training and managing calorie intake helps.'}],
    related:['pcos-risk-calculator','thyroid-risk-calculator','biological-age-calculator','stress-level-calculator']
  },

  { slug:'macro-timing-calculator', name:'Macro Timing Calculator', desc:'Calculate optimal macronutrient distribution for pre-workout, post-workout, and other meals.', icon:'food', category:'Nutrition',
    fields:[{id:'calories',label:'Total Daily Calories',type:'number',ph:'2200'},{id:'protein',label:'Daily Protein Goal (g)',type:'number',ph:'150'},{id:'meals',label:'Meals Per Day',type:'number',ph:'4'},{id:'workouttime',label:'Workout Timing',type:'select',options:['Morning (6-9am)','Midday (11am-1pm)','Afternoon (3-5pm)','Evening (6-8pm)']}],
    logic:`var cal=parseFloat(document.getElementById('calories').value);var prot=parseFloat(document.getElementById('protein').value);var meals=Math.max(2,Math.min(6,parseFloat(document.getElementById('meals').value)||4));var wt=document.getElementById('workouttime').value;if(!cal||!prot){alert('Fill all fields');return;}var preCal=Math.round(cal*0.25);var postCal=Math.round(cal*0.30);var restCal=cal-preCal-postCal;var preCarbs=Math.round(preCal*0.5/4);var postCarbs=Math.round(postCal*0.4/4);var preP=Math.round(prot*0.2);var postP=Math.round(prot*0.35);var restP=prot-preP-postP;showResult('result',wt+' Workout','Meal Timing Guide','PRE-workout (1-2hr before): ~'+preCal+' kcal | '+preP+'g protein | '+preCarbs+'g carbs. POST-workout (within 1hr): ~'+postCal+' kcal | '+postP+'g protein | '+postCarbs+'g carbs. Remaining '+Math.round(restCal)+' kcal & '+restP+'g protein spread over other '+Math.max(1,meals-2)+' meal(s).','green');`,
    article:`<h2>Macro Timing Calculator</h2><p>Nutrient timing — strategically distributing your macronutrients around your workout — can enhance performance, recovery, and body composition results. While the overall quality and quantity of your diet matters most, optimizing when you eat protein and carbohydrates can provide meaningful additional benefits for those training seriously.</p><h3>The Anabolic Window</h3><p>Post-workout is the most critical period for nutrition. Muscle protein synthesis is elevated for 24-48 hours after training, but peaks within the first 2 hours. Consuming 30-50g of protein and fast-digesting carbohydrates within 1-2 hours post-workout optimizes muscle repair and glycogen replenishment.</p>`,
    faqs:[{q:'When should I eat before a workout?',a:'Eat a full meal 2-3 hours before, or a small snack (30-60g carbs + 15-20g protein) 30-60 minutes before training.'},{q:'What should I eat post-workout?',a:'30-50g protein (whey, chicken, Greek yogurt) and 30-60g fast carbs (rice, banana, pasta) within 1-2 hours.'},{q:'Does meal timing matter as much as total intake?',a:'For most people, total daily calories and macros matter more than timing. Timing provides additional benefits for serious athletes.'},{q:'Should I train fasted?',a:'Fasted cardio burns more fat during exercise but does not necessarily improve overall fat loss. If performance suffers, eat before training.'},{q:'How many meals should I eat per day?',a:'3-6 meals works well for most people. Frequent meals help maintain protein synthesis and blood sugar stability throughout the day.'}],
    related:['calorie-calculator','macro-calculator','protein-intake-calculator','keto-calculator']
  },

  // ─── GROUP 3: MENTAL HEALTH & WELLNESS ─────────────────────────────────────

  { slug:'burnout-risk-calculator', name:'Burnout Risk Calculator', desc:'Assess your risk of workplace and emotional burnout with this validated screening tool.', icon:'brain', category:'Mental Health',
    fields:[{id:'exhaust',label:'Emotional Exhaustion (0-4)',type:'number',ph:'2'},{id:'detach',label:'Feeling Detached/Cynical (0-4)',type:'number',ph:'2'},{id:'ineffect',label:'Feeling Ineffective (0-4)',type:'number',ph:'2'},{id:'workload',label:'Overwhelming Workload (0-4)',type:'number',ph:'2'},{id:'control',label:'Lack of Control (0-4)',type:'number',ph:'2'},{id:'sleep',label:'Work-Related Sleep Problems (0-4)',type:'number',ph:'2'},{id:'recovery',label:'Poor Work Recovery (0-4)',type:'number',ph:'2'}],
    logic:`var e=parseFloat(document.getElementById('exhaust').value)||0;var d=parseFloat(document.getElementById('detach').value)||0;var i=parseFloat(document.getElementById('ineffect').value)||0;var w=parseFloat(document.getElementById('workload').value)||0;var c=parseFloat(document.getElementById('control').value)||0;var s=parseFloat(document.getElementById('sleep').value)||0;var r=parseFloat(document.getElementById('recovery').value)||0;var total=e+d+i+w+c+s+r;var max=28;var pct=Math.round(total/max*100);var col=pct<=30?'green':pct<=60?'yellow':'red';var l=pct<=30?'Low Burnout Risk':pct<=60?'Moderate Burnout Risk':'High Burnout Risk';var s2=pct<=30?'Your burnout indicators are low. Continue prioritizing work-life balance and recovery practices.':pct<=60?'You show moderate burnout warning signs. Prioritize recovery time, set boundaries, and speak with your manager or a counselor if needed.':'You show significant burnout symptoms. Please reach out to a mental health professional, consider speaking to HR, and prioritize urgent self-care and recovery.';showResult('result',pct+'%',l,s2,col);`,
    article:`<h2>Burnout Risk Calculator</h2><p>Burnout is a state of chronic stress that leads to physical and emotional exhaustion, cynicism and detachment, and feelings of ineffectiveness. The World Health Organization officially recognizes burnout as an occupational phenomenon. It is most common in helping professions (healthcare, education, social work), high-pressure corporate environments, and among caregivers — but it can affect anyone.</p><h3>The Three Dimensions of Burnout</h3><p>According to Maslach's Burnout Inventory, burnout has three core dimensions: emotional exhaustion (depleted emotional resources), depersonalization (cynicism and detachment from work/people), and reduced personal accomplishment (feelings of ineffectiveness). Early recognition allows intervention before full burnout develops.</p>`,
    faqs:[{q:'What is burnout?',a:'Burnout is a state of chronic workplace stress characterized by exhaustion, cynicism, and reduced effectiveness.'},{q:'How long does it take to recover from burnout?',a:'Recovery varies from weeks to years depending on severity. It typically requires time off, therapy, and significant lifestyle changes.'},{q:'Can you have burnout without working too much?',a:'Yes. Burnout can result from emotional labor, lack of autonomy, poor relationships, or values mismatch, not just overwork.'},{q:'Is burnout the same as depression?',a:'They share symptoms but are different. Burnout is primarily work-related and context-specific; depression affects all areas of life.'},{q:'What helps prevent burnout?',a:'Clear boundaries, adequate rest, meaningful work, social support, autonomy, and regular recovery activities (vacation, hobbies, exercise).'}],
    related:['stress-level-calculator','anxiety-score-calculator','sleep-debt-calculator','depression-screening-calculator']
  },

  { slug:'focus-score-calculator', name:'Focus & Concentration Score', desc:'Assess your current focus ability and attention span with this quick assessment.', icon:'brain', category:'Mental Health',
    fields:[{id:'distract',label:'Easily Distracted? (0-4)',type:'number',ph:'2'},{id:'complete',label:'Difficulty Completing Tasks? (0-4)',type:'number',ph:'2'},{id:'forget',label:'Forgetfulness? (0-4)',type:'number',ph:'2'},{id:'wander',label:'Mind Wandering? (0-4)',type:'number',ph:'2'},{id:'sleep',label:'Sleep Quality (0-4, 4=great)',type:'number',ph:'3'},{id:'exercise',label:'Daily Exercise? (0-4, 4=daily)',type:'number',ph:'2'}],
    logic:`var d=parseFloat(document.getElementById('distract').value)||0;var c=parseFloat(document.getElementById('complete').value)||0;var f=parseFloat(document.getElementById('forget').value)||0;var w=parseFloat(document.getElementById('wander').value)||0;var sl=parseFloat(document.getElementById('sleep').value)||3;var ex=parseFloat(document.getElementById('exercise').value)||2;var negScore=d+c+f+w;var posScore=sl+ex;var score=Math.max(0,Math.min(100,Math.round((1-negScore/16)*50+(posScore/8)*50)));var col=score>=70?'green':score>=45?'yellow':'red';var l=score>=70?'Good Focus':score>=45?'Moderate Focus':'Poor Focus';var s=score>=70?'Your focus score is strong. Maintain good sleep, exercise, and minimize digital distractions to stay sharp.':score>=45?'Your focus is moderate. Try techniques like Pomodoro (25-min blocks), morning exercise, and limiting social media to improve concentration.':'Your focus score is low. Prioritize sleep quality, add daily physical activity, practice mindfulness meditation, and consider speaking with a doctor to rule out ADHD or other conditions.';showResult('result',score+'/100',l,s,col);`,
    article:`<h2>Focus & Concentration Score Calculator</h2><p>Focus and concentration are essential for productivity, learning, and wellbeing. Modern life — with constant notifications, multitasking demands, and digital stimulation — presents unprecedented challenges to sustained attention. This calculator assesses your current focus ability and provides targeted strategies for improvement.</p><h3>What Affects Focus?</h3><p>Sleep is the single biggest predictor of focus — even mild sleep deprivation degrades concentration equivalent to being legally drunk. Exercise increases BDNF (brain-derived neurotrophic factor), literally growing neural connections that support focus. Chronic stress floods the brain with cortisol, which impairs prefrontal cortex function — the area responsible for attention control.</p>`,
    faqs:[{q:'How can I improve my focus quickly?',a:'Prioritize 7-9 hours of sleep, exercise in the morning, eliminate phone notifications during work blocks, and stay hydrated.'},{q:'What is ADHD and how is it different from poor focus?',a:'ADHD is a neurodevelopmental condition with persistent, pervasive attention difficulties. Poor situational focus can affect anyone and is often reversible.'},{q:'Does caffeine help focus?',a:'Caffeine improves alertness and reaction time temporarily, but overconsumption causes anxiety and crashes. Use strategically.'},{q:'How long should a focus session be?',a:'Research suggests 25-90 minutes is optimal depending on task difficulty and your current capacity. Pomodoro (25-min) blocks work well for many people.'},{q:'Does social media worsen focus?',a:'Yes. Frequent context-switching from social media trains the brain toward distraction patterns. Digital detox periods help restore focus capacity.'}],
    related:['burnout-risk-calculator','stress-level-calculator','sleep-hygiene-calculator','productivity-score-calculator']
  },

  { slug:'sleep-hygiene-calculator', name:'Sleep Hygiene Score', desc:'Evaluate your sleep hygiene habits and get personalized tips for better rest.', icon:'sleep', category:'Wellness',
    fields:[{id:'bedtime',label:'Consistent Bedtime? (0-3)',type:'number',ph:'2'},{id:'screen',label:'Screen-Free Before Bed? (0-3)',type:'number',ph:'1'},{id:'caffeine',label:'No Caffeine After 2pm? (0-3)',type:'number',ph:'2'},{id:'temp',label:'Cool Room (16-19°C)? (0-3)',type:'number',ph:'2'},{id:'dark',label:'Dark/Quiet Room? (0-3)',type:'number',ph:'2'},{id:'wind',label:'Wind-Down Routine? (0-3)',type:'number',ph:'1'},{id:'alcohol',label:'Avoid Alcohol Before Bed? (0-3)',type:'number',ph:'2'}],
    logic:`var b=parseFloat(document.getElementById('bedtime').value)||0;var sc=parseFloat(document.getElementById('screen').value)||0;var ca=parseFloat(document.getElementById('caffeine').value)||0;var tp=parseFloat(document.getElementById('temp').value)||0;var dk=parseFloat(document.getElementById('dark').value)||0;var wd=parseFloat(document.getElementById('wind').value)||0;var al=parseFloat(document.getElementById('alcohol').value)||0;var total=b+sc+ca+tp+dk+wd+al;var max=21;var pct=Math.round(total/max*100);var col=pct>=75?'green':pct>=50?'yellow':'red';var l=pct>=75?'Excellent Sleep Hygiene':pct>=50?'Good Sleep Hygiene':'Poor Sleep Hygiene';var tips=[];if(sc<2)tips.push('Avoid screens 60+ min before bed');if(b<2)tips.push('Set a consistent sleep/wake time');if(ca<2)tips.push('No caffeine after 2pm');if(wd<2)tips.push('Add a 30-min wind-down routine');var tStr=tips.length?'Top improvements: '+tips.join('; ')+'.':'Keep up your excellent habits!';showResult('result',pct+'%',l,'Sleep hygiene score: '+total+'/21. '+tStr,col);`,
    article:`<h2>Sleep Hygiene Score Calculator</h2><p>Sleep hygiene refers to the habits and practices that promote consistent, restorative sleep. Poor sleep hygiene is among the most common and correctable causes of insomnia and poor sleep quality. Research consistently shows that behavioral changes — not medication — are the most effective long-term treatment for sleep problems.</p><h3>The Science of Sleep Hygiene</h3><p>Your circadian rhythm — the internal 24-hour clock regulating sleep — is sensitive to light, temperature, timing, and behavior. Consistent sleep/wake times, even on weekends, are the single most important sleep hygiene practice. Exposure to bright light in the morning and darkness in the evening helps regulate melatonin secretion and sleep onset.</p>`,
    faqs:[{q:'What is sleep hygiene?',a:'The collection of habits and environmental practices that promote healthy, consistent, restorative sleep.'},{q:'How long before bed should I avoid screens?',a:'At least 60 minutes. The blue light from screens suppresses melatonin production and delays sleep onset.'},{q:'Does a warm bath help sleep?',a:'Yes! A warm bath 1-2 hours before bed causes your body temperature to drop when you get out, triggering sleepiness.'},{q:'Can melatonin supplements help?',a:'Low-dose melatonin (0.5-3 mg) helps with sleep timing shifts (jet lag, shift work) but is not a treatment for chronic insomnia.'},{q:'What temperature should my bedroom be?',a:'Research consistently shows 16-19°C (60-67°F) is optimal for sleep. The body needs to drop core temperature to initiate sleep.'}],
    related:['sleep-debt-calculator','stress-level-calculator','sleep-calculator','burnout-risk-calculator']
  },

  { slug:'productivity-score-calculator', name:'Productivity Score Calculator', desc:'Assess your daily productivity habits and find areas for improvement.', icon:'brain', category:'Mental Health',
    fields:[{id:'goals',label:'Clear Daily Goals? (0-4)',type:'number',ph:'3'},{id:'priority',label:'Tackle Priority Tasks First? (0-4)',type:'number',ph:'2'},{id:'distract',label:'Low Distraction Environment? (0-4)',type:'number',ph:'2'},{id:'breaks',label:'Regular Breaks? (0-4)',type:'number',ph:'2'},{id:'sleep',label:'Getting 7-9h Sleep? (0-4)',type:'number',ph:'3'},{id:'exercise',label:'Daily Exercise? (0-4)',type:'number',ph:'2'}],
    logic:`var g=parseFloat(document.getElementById('goals').value)||0;var p=parseFloat(document.getElementById('priority').value)||0;var d=parseFloat(document.getElementById('distract').value)||0;var b=parseFloat(document.getElementById('breaks').value)||0;var s=parseFloat(document.getElementById('sleep').value)||0;var e=parseFloat(document.getElementById('exercise').value)||0;var total=g+p+d+b+s+e;var max=24;var pct=Math.round(total/max*100);var col=pct>=75?'green':pct>=50?'yellow':'red';var l=pct>=75?'High Productivity':pct>=50?'Moderate Productivity':'Low Productivity';var s2=pct>=75?'Excellent habits! You have a strong productivity foundation. Continue refining systems as your goals evolve.':pct>=50?'Good foundations with room to grow. Focus on planning the night before, blocking distraction, and protecting your best hours for deep work.':'Significant improvement opportunities exist. Start with one change: either consistent sleep time or a morning planning ritual — these two habits create a cascade of productivity gains.';showResult('result',pct+'%',l,s2,col);`,
    article:`<h2>Productivity Score Calculator</h2><p>Personal productivity is less about time management and more about energy management, attention control, and strategic prioritization. High performers do not work harder — they work smarter by protecting their peak focus hours, delegating ruthlessly, and recovering fully. This calculator assesses the foundational habits that drive sustained high performance.</p>`,
    faqs:[{q:'What is the most important productivity habit?',a:'Sleep. Even one night of poor sleep degrades cognitive performance equivalent to having a 0.1% blood alcohol level.'},{q:'How does exercise affect productivity?',a:'A single 20-minute aerobic session improves focus, memory, and mood for up to 4 hours afterward.'},{q:'Is multitasking effective?',a:'No. The brain cannot truly multitask complex tasks — it rapidly context-switches, reducing efficiency by up to 40%.'},{q:'What is deep work?',a:'Intense, uninterrupted focus on cognitively demanding tasks. Cal Newport\'s concept argues it produces the most valuable output per hour.'},{q:'How many productive hours does the brain have per day?',a:'Research suggests the brain has 3-5 hours of peak focus capacity per day. Use these for your most important work.'}],
    related:['burnout-risk-calculator','focus-score-calculator','sleep-hygiene-calculator','stress-level-calculator']
  },

  { slug:'digital-detox-calculator', name:'Digital Detox Calculator', desc:'Calculate your daily screen time impact and get a personalized digital detox plan.', icon:'brain', category:'Mental Health',
    fields:[{id:'phone',label:'Daily Phone Time (hours)',type:'number',ph:'4'},{id:'computer',label:'Daily Computer Time (hours)',type:'number',ph:'6'},{id:'tv',label:'Daily TV/Streaming (hours)',type:'number',ph:'2'},{id:'social',label:'Social Media (hours)',type:'number',ph:'2'}],
    logic:`var ph=parseFloat(document.getElementById('phone').value)||0;var pc=parseFloat(document.getElementById('computer').value)||0;var tv=parseFloat(document.getElementById('tv').value)||0;var sm=parseFloat(document.getElementById('social').value)||0;var total=ph+pc+tv;var weekly=Math.round(total*7);var yearly=Math.round(total*365);var c=total<=4?'green':total<=8?'yellow':'red';var l=total<=4?'Healthy Screen Time':total<=8?'High Screen Time':'Excessive Screen Time';var recs='';if(sm>2)recs+='Set app time limits for social media (max 30 min/day). ';if(ph>3)recs+='Use phone grayscale mode and bedroom-free zones. ';if(tv>2)recs+='Replace one hour of TV with a walk, reading, or social activity. ';showResult('result',total+'h/day',l,'Total: '+total+' hrs/day | '+weekly+' hrs/week | '+yearly+' hrs/year ('+Math.round(yearly/8760*100)+'% of waking hours). '+recs,'green');`,
    article:`<h2>Digital Detox Calculator</h2><p>The average person now spends over 7 hours daily looking at screens — that is nearly half their waking life. Research links excessive screen time to disrupted sleep, increased anxiety and depression, reduced attention span, eye strain, and sedentary lifestyle. A digital detox does not mean eliminating technology; it means creating intentional boundaries to restore balance and mental health.</p>`,
    faqs:[{q:'How much screen time is too much?',a:'For adults, WHO guidelines do not specify limits, but research suggests negative effects appear above 4+ hours of recreational screen time.'},{q:'Does screen time cause depression?',a:'Heavy social media use correlates with depression in adolescents. The relationship in adults is complex — passive scrolling is worse than active engagement.'},{q:'What is a digital detox?',a:'A period of intentionally reducing or eliminating screen use to reduce stress, improve sleep, and reconnect with offline activities.'},{q:'How do I reduce screen time?',a:'Use built-in screen time limits, charge phones outside the bedroom, implement tech-free meal times, and schedule offline activities.'},{q:'Are blue light glasses helpful?',a:'Evidence is mixed. Blue light glasses may help with eye strain but have limited effect on sleep — reducing screen brightness matters more.'}],
    related:['focus-score-calculator','sleep-hygiene-calculator','burnout-risk-calculator','stress-level-calculator']
  },

  // ─── GROUP 4: FITNESS & PERFORMANCE ────────────────────────────────────────

  { slug:'strength-level-calculator', name:'Strength Level Calculator', desc:'Assess your strength level for bench press, squat, and deadlift relative to body weight.', icon:'fitness', category:'Fitness',
    fields:[{id:'weight',label:'Body Weight (kg)',type:'number',ph:'80'},{id:'bench',label:'Bench Press 1RM (kg)',type:'number',ph:'80'},{id:'squat',label:'Squat 1RM (kg)',type:'number',ph:'100'},{id:'deadlift',label:'Deadlift 1RM (kg)',type:'number',ph:'120'},{id:'gender',label:'Gender',type:'select',options:['Male','Female']}],
    logic:`var bw=parseFloat(document.getElementById('weight').value);var bp=parseFloat(document.getElementById('bench').value);var sq=parseFloat(document.getElementById('squat').value);var dl=parseFloat(document.getElementById('deadlift').value);var g=document.getElementById('gender').value;if(!bw){alert('Enter body weight');return;}var benchRatio=bp?bp/bw:0;var squatRatio=sq?sq/bw:0;var deadRatio=dl?dl/bw:0;var levels=g==='Male'?{novice:[0.5,0.75,1],intermediate:[1,1.25,1.5],advanced:[1.5,1.75,2],elite:[2,2.25,2.5]}:{novice:[0.35,0.5,0.65],intermediate:[0.75,1,1.15],advanced:[1.1,1.4,1.6],elite:[1.5,1.8,2]};function getLevel(r,lev){return r>=lev.elite[0]?'Elite':r>=lev.advanced[0]?'Advanced':r>=lev.intermediate[0]?'Intermediate':r>=lev.novice[0]?'Novice':'Beginner';}var bl=getLevel(benchRatio,levels);var sl=getLevel(squatRatio,levels);var dl2=getLevel(deadRatio,levels);var parts=[];if(bp)parts.push('Bench: '+bp+'kg ('+benchRatio.toFixed(2)+'x BW) = '+bl);if(sq)parts.push('Squat: '+sq+'kg ('+squatRatio.toFixed(2)+'x BW) = '+sl);if(dl)parts.push('Deadlift: '+dl+'kg ('+deadRatio.toFixed(2)+'x BW) = '+dl2);showResult('result',bl,'Overall Strength Level',parts.join(' | ')+'. Use progressive overload to advance to the next level — add 2.5-5kg per session for compound lifts.','green');`,
    article:`<h2>Strength Level Calculator</h2><p>Strength standards allow you to compare your lifting performance to population benchmarks and understand where you fall on the strength spectrum — from beginner through elite. The most meaningful comparison is your lift relative to body weight (strength-to-weight ratio), which levels the playing field between lighter and heavier athletes.</p><h3>Strength Levels Explained</h3><p>Beginner: Just learning technique. Novice: 1-6 months of consistent training. Intermediate: 1-3 years. Advanced: 3-5+ years. Elite: Top 1-5% of lifters. Progression gets slower as you advance — moving from beginner to intermediate may take months, while advancing from advanced to elite can take years of dedicated work.</p>`,
    faqs:[{q:'What is a good bench press ratio?',a:'For men: 1.0x bodyweight is intermediate; 1.5x is advanced. For women: 0.75x is intermediate; 1.1x is advanced.'},{q:'What is a good squat ratio?',a:'For men: 1.25x bodyweight is intermediate; 1.75x is advanced. For women: 1.0x is intermediate; 1.4x is advanced.'},{q:'How do I calculate my 1RM?',a:'Use the One Rep Max Calculator: lift weight × (1 + reps/30). Or attempt a true single with proper spotting.'},{q:'Should I compare to powerlifters or general standards?',a:'These standards reflect the general strength training population, not competitive powerlifters. Elite here represents the top 5% of gym-goers.'},{q:'How fast should I progress?',a:'Beginners can add weight each session. Intermediates weekly. Advanced lifters may progress monthly. Consistency beats frequency.'}],
    related:['one-rep-max-calculator','vo2-max-calculator','body-fat-calculator','marathon-time-predictor']
  },

  { slug:'marathon-time-predictor', name:'Marathon Time Predictor', desc:'Predict your marathon or half marathon finish time from a recent race or training pace.', icon:'fitness', category:'Fitness',
    fields:[{id:'dist',label:'Known Distance',type:'select',options:['5K','10K','Half Marathon','Recent Long Run']},{id:'time',label:'Finish Time (minutes)',type:'number',ph:'25'},{id:'goal',label:'Goal Race',type:'select',options:['5K','10K','Half Marathon (21.1km)','Marathon (42.2km)']}],
    logic:`var dist={'5K':5,'10K':10,'Half Marathon':21.1,'Recent Long Run':16}[document.getElementById('dist').value]||10;var t=parseFloat(document.getElementById('time').value);var goal={'5K':5,'10K':10,'Half Marathon (21.1km)':21.1,'Marathon (42.2km)':42.2}[document.getElementById('goal').value]||42.2;if(!t){alert('Enter your time');return;}var pace=t/dist;var predicted=Math.round(pace*goal*Math.pow(goal/dist,0.07));var ph=Math.floor(predicted/60);var pm=predicted%60;var perKm=Math.round(predicted/goal);var pkm_m=Math.floor(perKm/60);var pkm_s=perKm%60;showResult('result',ph+'h '+pm+'m','Predicted '+document.getElementById('goal').value+' Time','Required pace: '+pkm_m+':'+(pkm_s<10?'0':'')+pkm_s+'/km. This prediction uses the Riegel formula which accounts for fatigue factor over longer distances. Train at 80% easy pace + 20% hard intervals for optimal results.','green');`,
    article:`<h2>Marathon Time Predictor</h2><p>Accurately predicting your marathon or race time helps you set a realistic goal pace, plan your training, and avoid the most common racing mistake — going out too fast. Our predictor uses the Riegel formula (developed by Pete Riegel in 1977), which accounts for the exponential fatigue factor over increasing distances.</p><h3>The Riegel Formula</h3><p>T2 = T1 × (D2/D1)^1.07, where T1 is your known time for distance D1, and T2 predicts your time for target distance D2. The 1.07 exponent represents how fatigue grows exponentially with distance — explaining why marathon pace is significantly slower than 10K pace, even for very fit runners.</p>`,
    faqs:[{q:'Is the marathon time predictor accurate?',a:'Within 5-10% for most runners. Factors like course terrain, weather, training volume, and race experience affect actual performance.'},{q:'What pace should I train at?',a:'80% of training should be at conversational (easy) pace. Only 20% at race-specific or harder efforts — the 80/20 rule.'},{q:'How do I qualify for Boston Marathon?',a:'Boston Qualifying standards range from 3:00 (Male 18-34) to 5:25 (Female 80+). Check the BAA website for your age group standard.'},{q:'How long should I train for a marathon?',a:'Most plans are 16-20 weeks. Beginners should have a solid 5-10K base before starting marathon-specific training.'},{q:'What is the most common marathon mistake?',a:'Going out too fast. Most runners who blow up started 10-30 seconds per km faster than their goal pace in the first half.'}],
    related:['running-pace-calculator','vo2-max-calculator','heart-rate-calculator','steps-to-calories-calculator']
  },

  { slug:'hiit-calories-calculator', name:'HIIT Calorie Calculator', desc:'Calculate calories burned during HIIT workouts based on intensity, duration, and body weight.', icon:'fitness', category:'Fitness',
    fields:[{id:'weight',label:'Weight (kg)',type:'number',ph:'75'},{id:'duration',label:'HIIT Duration (minutes)',type:'number',ph:'20'},{id:'intensity',label:'Intensity Level',type:'select',options:['Moderate (e.g., basic circuits)','High (e.g., sprint intervals)','Very High (e.g., Tabata, CrossFit)']},{id:'fitness',label:'Fitness Level',type:'select',options:['Beginner','Intermediate','Advanced']}],
    logic:`var w=parseFloat(document.getElementById('weight').value);var d=parseFloat(document.getElementById('duration').value);var intens=document.getElementById('intensity').value;var fit=document.getElementById('fitness').value;if(!w||!d){alert('Fill all fields');return;}var met={'Moderate (e.g., basic circuits)':8,'High (e.g., sprint intervals)':12,'Very High (e.g., Tabata, CrossFit)':15}[intens]||10;var fitMult={'Beginner':0.85,'Intermediate':1.0,'Advanced':1.1}[fit]||1;var cal=Math.round(met*w*d/60*fitMult);var epoc=Math.round(cal*0.15);var total=cal+epoc;showResult('result',total+' kcal','HIIT + EPOC Calories Burned','During workout: ~'+cal+' kcal | EPOC (afterburn effect): +'+epoc+' kcal | Total estimated burn: ~'+total+' kcal. HIIT burns '+Math.round(cal/d)+' kcal/minute vs ~'+Math.round(met*0.6*w/60)+' for steady-state cardio.','green');`,
    article:`<h2>HIIT Calorie Calculator</h2><p>High-Intensity Interval Training (HIIT) burns more calories per minute than steady-state cardio AND creates a significant "afterburn" effect (EPOC — Excess Post-exercise Oxygen Consumption). This means you continue burning extra calories for hours after the workout ends. Studies show HIIT can increase metabolic rate for 24-48 hours post-exercise.</p><h3>Why HIIT Is Efficient</h3><p>A 20-minute HIIT session can burn as many total calories (including EPOC) as 40-60 minutes of moderate steady-state cardio. HIIT also improves insulin sensitivity, VO2 max, and preserves muscle mass better than long-duration cardio — making it particularly effective for body recomposition.</p>`,
    faqs:[{q:'How many calories does 20 minutes of HIIT burn?',a:'Typically 200-400 calories during the session, plus an additional 15-25% through EPOC (afterburn effect).'},{q:'What is EPOC (afterburn)?',a:'Excess Post-exercise Oxygen Consumption — elevated calorie burn after intense exercise as the body restores itself to baseline.'},{q:'How often should I do HIIT?',a:'2-3 times per week maximum for most people. HIIT is very taxing — adequate recovery (48-72 hours) between sessions is essential.'},{q:'Is HIIT better than running for weight loss?',a:'HIIT is more time-efficient and preserves more muscle. Long-duration running burns more total calories per session.'},{q:'Can beginners do HIIT?',a:'Yes, but start with lower intensity (work:rest ratios like 20 seconds on / 40 seconds off) and build gradually.'}],
    related:['heart-rate-calculator','vo2-max-calculator','calorie-calculator','steps-to-calories-calculator']
  },

  { slug:'step-goal-calculator', name:'Step Goal Calculator', desc:'Calculate your personalized daily step goal based on your health objectives.', icon:'fitness', category:'Fitness',
    fields:[{id:'weight',label:'Weight (kg)',type:'number',ph:'75'},{id:'height',label:'Height (cm)',type:'number',ph:'170'},{id:'goal',label:'Health Goal',type:'select',options:['General Health','Weight Loss','Heart Health','Active Lifestyle','Athletic Performance']},{id:'current',label:'Current Daily Steps (average)',type:'number',ph:'5000'}],
    logic:`var w=parseFloat(document.getElementById('weight').value);var h=parseFloat(document.getElementById('height').value);var goal=document.getElementById('goal').value;var curr=parseFloat(document.getElementById('current').value)||5000;var base={'General Health':8000,'Weight Loss':12000,'Heart Health':10000,'Active Lifestyle':10000,'Athletic Performance':15000}[goal]||10000;var strideM=(h*0.413)/100;var target=base;var calories=Math.round(target*0.04*w/70);var km=(target*strideM/1000).toFixed(1);var increase=Math.max(0,target-curr);showResult('result',target.toLocaleString()+' steps/day','Your Daily Step Goal','Goal: '+goal+' | Distance: ~'+km+' km | Calories: ~'+calories+' kcal | Increase from current: +'+increase.toLocaleString()+' steps. Tip: Increase by no more than 10% per week to avoid injury.','green');`,
    article:`<h2>Step Goal Calculator</h2><p>While the 10,000-step goal originated from a Japanese marketing campaign in 1965, modern research validates it as a meaningful target for health. Studies show that each additional 1,000 steps per day is associated with a 15% reduction in mortality risk. The goal is not magic — it represents approximately 8km of walking, which provides significant cardiovascular, metabolic, and mental health benefits.</p><h3>Steps and Health Outcomes</h3><p>Research published in JAMA Internal Medicine found benefits plateau around 7,500 steps for older adults. For younger adults and weight loss, higher targets (10,000-15,000) provide additional benefits. Even moving from 2,000 to 5,000 steps produces meaningful health improvements compared to sedentary baseline.</p>`,
    faqs:[{q:'Is 10,000 steps really necessary?',a:'Research shows significant health benefits start around 7,000-8,000 steps. 10,000 is an achievable, meaningful target for most people.'},{q:'How many calories does 10,000 steps burn?',a:'Approximately 300-500 calories for most adults, depending on weight, pace, and terrain.'},{q:'How far is 10,000 steps?',a:'Roughly 7-8 km (4.5-5 miles) for an adult with an average stride length.'},{q:'Can I break steps into multiple sessions?',a:'Yes. Accumulated steps throughout the day have equivalent health benefits to a single continuous walk.'},{q:'What if I cannot reach 10,000 steps?',a:'Any increase from your baseline is beneficial. Even moving from sedentary to 5,000 steps significantly reduces health risks.'}],
    related:['steps-to-calories-calculator','running-pace-calculator','hiit-calories-calculator','heart-rate-calculator']
  },

  { slug:'injury-risk-calculator', name:'Injury Risk Calculator', desc:'Assess your risk of exercise-related injury based on training habits and biomechanics.', icon:'fitness', category:'Fitness',
    fields:[{id:'increase',label:'Weekly Training Increase (%)',type:'number',ph:'10'},{id:'warmup',label:'Always Warm Up? (0-4)',type:'number',ph:'3'},{id:'sleep',label:'Sleep Quality (0-4)',type:'number',ph:'3'},{id:'history',label:'Previous Injuries?',type:'select',options:['None','Minor (>6 months ago)','Recent (<6 months)']},{id:'pain',label:'Training Through Pain?',type:'select',options:['Never','Occasionally','Often']},{id:'rest',label:'Rest Days Per Week',type:'number',ph:'2'}],
    logic:`var inc=parseFloat(document.getElementById('increase').value)||10;var wu=parseFloat(document.getElementById('warmup').value)||3;var sl=parseFloat(document.getElementById('sleep').value)||3;var hist={'None':0,'Minor (>6 months ago)':2,'Recent (<6 months)':5}[document.getElementById('history').value]||0;var pain={'Never':0,'Occasionally':2,'Often':4}[document.getElementById('pain').value]||0;var rest=parseFloat(document.getElementById('rest').value)||2;var score=0;if(inc>20)score+=3;else if(inc>10)score+=1;score+=(4-wu)+(4-sl)+hist+pain;if(rest<1)score+=3;else if(rest<2)score+=1;var max=20;var pct=Math.round(score/max*100);var c=pct<=30?'green':pct<=60?'yellow':'red';var l=pct<=30?'Low Injury Risk':pct<=60?'Moderate Risk':'High Injury Risk';var s=pct<=30?'Your training practices are safe. Maintain the 10% rule for volume increases and consistent recovery.':pct<=60?'Several injury risk factors present. Review your training load progression, ensure adequate warm-ups, and prioritize sleep.':'High injury risk detected. Please reduce training volume, address any current pain with a physiotherapist, and ensure 2+ rest days weekly.';showResult('result',pct+'%',l,s,c);`,
    article:`<h2>Injury Risk Calculator</h2><p>Sports and exercise injuries are rarely random — most follow predictable patterns rooted in training errors. The two most common causes are doing too much too soon (violating the 10% rule for volume increases) and insufficient recovery. Understanding your injury risk profile allows you to train smarter, not just harder.</p><h3>The 10% Rule</h3><p>Never increase your weekly training volume (mileage, sets, or duration) by more than 10% per week. This rule applies to running, weightlifting, swimming, and most endurance sports. Ignoring it is the single most common cause of overuse injuries like stress fractures, tendinitis, and runner's knee.</p>`,
    faqs:[{q:'What is the most common exercise injury?',a:'Runner\'s knee (patellofemoral pain), shin splints, Achilles tendinitis, and lower back pain are the most common overuse injuries.'},{q:'How do I know if I should train through pain?',a:'Sharp, acute, or joint pain should stop your session immediately. Muscle soreness (DOMS) is generally fine to train through carefully.'},{q:'How long should I warm up?',a:'5-10 minutes of light aerobic activity followed by dynamic stretching specific to your planned workout.'},{q:'Does stretching prevent injuries?',a:'Dynamic stretching before exercise may reduce acute injury risk. Static stretching is better post-exercise for flexibility.'},{q:'How important is sleep for injury prevention?',a:'Very important. Sleep deprivation increases injury risk by impairing reaction time, coordination, and tissue repair.'}],
    related:['heart-rate-calculator','one-rep-max-calculator','strength-level-calculator','step-goal-calculator']
  },

  // ─── GROUP 5: NUTRITION TOOLS ───────────────────────────────────────────────

  { slug:'sugar-intake-calculator', name:'Sugar Intake Calculator', desc:'Calculate your daily sugar intake and see if it is within healthy limits.', icon:'food', category:'Nutrition',
    fields:[{id:'drinks',label:'Sugary Drinks per Day (sodas, juice)',type:'number',ph:'1'},{id:'sweet',label:'Sweets/Desserts per Day (servings)',type:'number',ph:'1'},{id:'processed',label:'Processed/Packaged Foods (servings)',type:'number',ph:'3'},{id:'fruit',label:'Fruit Servings per Day',type:'number',ph:'2'},{id:'added',label:'Teaspoons of Added Sugar',type:'number',ph:'2'}],
    logic:`var dr=parseFloat(document.getElementById('drinks').value)||0;var sw=parseFloat(document.getElementById('sweet').value)||0;var pr=parseFloat(document.getElementById('processed').value)||0;var fr=parseFloat(document.getElementById('fruit').value)||0;var ad=parseFloat(document.getElementById('added').value)||0;var addedSugar=dr*39+sw*20+pr*8+ad*4;var totalSugar=addedSugar+fr*12;var c=addedSugar<=25?'green':addedSugar<=50?'yellow':'red';var l=addedSugar<=25?'Within Guidelines':addedSugar<=50?'Moderately High':'Excessive';var who=25;showResult('result',addedSugar+'g added sugar','Daily Sugar Assessment','Added sugar: '+addedSugar+'g (WHO limit: '+who+'g/day for women, 36g for men). Total sugar (incl. fruit): '+totalSugar+'g. '+(addedSugar>who?'Reduce sugary drinks (biggest culprit), swap sweets for fruit, and read labels for hidden sugar (look for -ose suffixes).':'Great job keeping added sugar in check! Fruit sugar comes with fiber and nutrients — not a concern.'),c);`,
    article:`<h2>Sugar Intake Calculator</h2><p>The World Health Organization recommends less than 10% of daily calories from free (added) sugars — ideally under 5%, which equals about 25 grams (6 teaspoons) per day. Most people consume 2-3 times this amount. Excess sugar drives obesity, type 2 diabetes, tooth decay, fatty liver disease, and has been linked to cognitive decline.</p><h3>Hidden Sugar Sources</h3><p>Added sugar hides in surprising places: flavored yogurt (12g), breakfast cereal (10-15g per serving), fruit juice (24g per glass), sports drinks (34g), pasta sauce (10g per serving), and salad dressing (5-7g per tablespoon). Sugar has over 60 names on labels including high-fructose corn syrup, dextrose, maltose, and cane juice.</p>`,
    faqs:[{q:'How much sugar per day is acceptable?',a:'WHO recommends under 25g of added sugar per day. Natural sugars in whole fruit are not a health concern.'},{q:'Is fruit sugar bad?',a:'No. Fruit contains fiber that slows sugar absorption, plus vitamins and antioxidants. Whole fruit is healthy in normal amounts.'},{q:'Does sugar cause diabetes?',a:'Excess sugar contributes to obesity and insulin resistance, which are major risk factors for type 2 diabetes.'},{q:'What are the symptoms of too much sugar?',a:'Fatigue, frequent urination, skin problems, mood swings, dental cavities, and weight gain.'},{q:'Which foods have the most hidden sugar?',a:'Sugary drinks, flavored yogurt, cereal, fruit juice, and sauces contain surprisingly large amounts of added sugar.'}],
    related:['calorie-calculator','homa-ir-calculator','diabetes-risk-calculator','fiber-intake-calculator']
  },

  { slug:'electrolyte-calculator', name:'Electrolyte Needs Calculator', desc:'Calculate your daily electrolyte requirements for sodium, potassium, and magnesium.', icon:'water', category:'Nutrition',
    fields:[{id:'weight',label:'Body Weight (kg)',type:'number',ph:'75'},{id:'activity',label:'Activity Level',type:'select',options:['Sedentary','Moderately Active','Very Active (1hr+/day)','Elite Athlete']},{id:'climate',label:'Climate',type:'select',options:['Temperate','Hot/Humid']},{id:'sweat',label:'Sweat Level',type:'select',options:['Light Sweater','Moderate Sweater','Heavy Sweater']}],
    logic:`var w=parseFloat(document.getElementById('weight').value);var act=document.getElementById('activity').value;var clim=document.getElementById('climate').value;var swt=document.getElementById('sweat').value;if(!w){alert('Enter weight');return;}var na={'Sedentary':1500,'Moderately Active':2000,'Very Active (1hr+/day)':2500,'Elite Athlete':3000}[act]||2000;var k=Math.round(w*50);var mg=Math.round(w*6);if(clim==='Hot/Humid'){na+=500;k+=300;}if(swt==='Heavy Sweater')na+=600;if(swt==='Moderate Sweater')na+=300;showResult('result',na+'mg Na+','Daily Electrolyte Targets','Sodium (Na+): '+na+' mg/day | Potassium (K+): '+Math.min(k,4700)+' mg/day | Magnesium (Mg): '+Math.min(mg,420)+' mg/day. Sources: Na+ (salt, broth), K+ (bananas, potatoes, avocado), Mg (nuts, leafy greens, dark chocolate).','green');`,
    article:`<h2>Electrolyte Needs Calculator</h2><p>Electrolytes are minerals that carry an electrical charge and are essential for nerve function, muscle contraction, hydration balance, and pH regulation. The three most important dietary electrolytes are sodium, potassium, and magnesium. Both deficiency and excess can cause serious health problems.</p>`,
    faqs:[{q:'What are electrolytes?',a:'Minerals including sodium, potassium, magnesium, calcium, and chloride that regulate fluid balance, nerve signals, and muscle function.'},{q:'When do electrolyte needs increase?',a:'During intense exercise, hot weather, illness with vomiting/diarrhea, and following a low-carb or fasting diet.'},{q:'Should I drink electrolyte sports drinks?',a:'For exercise under 1 hour, water is sufficient. Longer or intense sessions benefit from electrolyte replacement.'},{q:'What are symptoms of low potassium?',a:'Muscle cramps, weakness, constipation, irregular heartbeat, and fatigue.'},{q:'What are the best food sources of electrolytes?',a:'Sodium: salt, pickles. Potassium: bananas, avocado, potato. Magnesium: nuts, seeds, leafy greens. Calcium: dairy, leafy greens.'}],
    related:['water-intake-calculator','sodium-intake-calculator','hydration-level-calculator','calorie-calculator']
  },

  { slug:'omega3-calculator', name:'Omega-3 Intake Calculator', desc:'Calculate your optimal daily omega-3 intake based on your health needs and diet.', icon:'food', category:'Nutrition',
    fields:[{id:'condition',label:'Primary Health Goal',type:'select',options:['General Health','Heart Health','Anti-Inflammatory','Brain Health','Pregnancy/Breastfeeding']},{id:'fish',label:'Fatty Fish Servings Per Week',type:'number',ph:'1'},{id:'flax',label:'Flaxseed/Chia (tbsp/day)',type:'number',ph:'0'},{id:'nuts',label:'Walnuts (handful/day)',type:'number',ph:'0'}],
    logic:`var cond=document.getElementById('condition').value;var fish=parseFloat(document.getElementById('fish').value)||0;var flax=parseFloat(document.getElementById('flax').value)||0;var nuts=parseFloat(document.getElementById('nuts').value)||0;var targets={'General Health':500,'Heart Health':1000,'Anti-Inflammatory':2000,'Brain Health':1000,'Pregnancy/Breastfeeding':1400}[cond]||500;var current=Math.round(fish*7*1500/7+flax*2300+nuts*0.7*2300);var gap=Math.max(0,targets-current);var c=current>=targets?'green':current>=targets*0.7?'yellow':'red';var l=current>=targets?'Target Met':'Additional Needed';showResult('result',current+' mg/day','Omega-3 Intake','Daily intake: ~'+current+' mg EPA+DHA | Target for '+cond+': '+targets+' mg | Gap: '+(gap>0?gap+' mg — consider fish oil supplements.':'none — your intake is sufficient!')+'  Sources: salmon (2000mg/serving), sardines (1500mg), mackerel (2500mg). Plant omega-3 (ALA) from flax/chia converts at only 5-10% efficiency.',c);`,
    article:`<h2>Omega-3 Intake Calculator</h2><p>Omega-3 fatty acids are essential polyunsaturated fats that the body cannot produce independently. The three main types are ALA (plant-based), EPA, and DHA (marine-based). EPA and DHA have the strongest research supporting cardiovascular protection, anti-inflammatory effects, brain health, and reduced risk of depression. Most people in Western countries are significantly omega-3 deficient.</p>`,
    faqs:[{q:'What foods are high in omega-3?',a:'Fatty fish (salmon, sardines, mackerel), fish oil supplements, flaxseed, chia seeds, walnuts, and algae oil.'},{q:'What is the difference between ALA, EPA, and DHA?',a:'ALA is plant-based; EPA and DHA are marine-based. The body converts ALA to EPA/DHA at only 5-10% efficiency, so direct EPA/DHA sources are more effective.'},{q:'How much omega-3 should I take?',a:'500mg EPA+DHA for general health; 1,000mg for heart health; 2,000-4,000mg for anti-inflammatory or high triglycerides.'},{q:'Should I take fish oil supplements?',a:'If you do not eat fatty fish 2-3 times weekly, high-quality fish oil or algae omega-3 supplements are recommended.'},{q:'Can I take too much omega-3?',a:'Very high doses (above 5g EPA+DHA) may increase bleeding risk. Doses up to 3g are generally considered safe for most adults.'}],
    related:['calorie-calculator','sugar-intake-calculator','electrolyte-calculator','fiber-intake-calculator']
  },

  { slug:'diet-comparison-calculator', name:'Diet Comparison Tool', desc:'Compare macronutrient ratios and calorie distribution across popular diets.', icon:'food', category:'Nutrition',
    fields:[{id:'calories',label:'Daily Calorie Target',type:'number',ph:'2000'},{id:'weight',label:'Body Weight (kg)',type:'number',ph:'75'},{id:'diet',label:'Diet to Compare',type:'select',options:['Standard Western','Mediterranean','Ketogenic','High Protein','Plant-Based','Paleo','Low Carb','Intermittent Fasting (16:8)']}],
    logic:`var cal=parseFloat(document.getElementById('calories').value)||2000;var w=parseFloat(document.getElementById('weight').value)||75;var diet=document.getElementById('diet').value;var profiles={'Standard Western':{p:0.15,c:0.55,f:0.30,score:4},'Mediterranean':{p:0.20,c:0.50,f:0.30,score:9},'Ketogenic':{p:0.20,c:0.05,f:0.75,score:7},'High Protein':{p:0.35,c:0.40,f:0.25,score:8},'Plant-Based':{p:0.15,c:0.60,f:0.25,score:9},'Paleo':{p:0.30,c:0.35,f:0.35,score:7},'Low Carb':{p:0.30,c:0.20,f:0.50,score:7},'Intermittent Fasting (16:8)':{p:0.25,c:0.45,f:0.30,score:8}};var d=profiles[diet];var pg=Math.round(cal*d.p/4);var cg=Math.round(cal*d.c/4);var fg=Math.round(cal*d.f/9);showResult('result',diet,'Diet Profile',diet+' macros at '+cal+' kcal: Protein '+pg+'g ('+Math.round(d.p*100)+'%) | Carbs '+cg+'g ('+Math.round(d.c*100)+'%) | Fat '+fg+'g ('+Math.round(d.f*100)+'%). Evidence score: '+d.score+'/10. Best for: '+({'Standard Western':'convenience (not health-optimized)','Mediterranean':'heart health, longevity, sustainability','Ketogenic':'rapid fat loss, epilepsy, insulin resistance','High Protein':'muscle building, satiety, weight loss','Plant-Based':'environmental impact, cardiovascular health','Paleo':'whole food approach, reducing processed foods','Low Carb':'blood sugar control, weight loss','Intermittent Fasting (16:8)':'metabolic flexibility, simplicity'}[diet]||'general health'),'green');`,
    article:`<h2>Diet Comparison Tool</h2><p>There is no universally perfect diet — the best diet is the one you can sustain long-term that meets your health goals and fits your lifestyle. However, research does rank diets by health outcomes. The Mediterranean diet consistently tops rankings for longevity, heart health, and sustainable weight management. Understanding the macronutrient profiles and evidence behind different diets helps you make an informed choice.</p>`,
    faqs:[{q:'Which diet is healthiest?',a:'The Mediterranean diet has the strongest research backing for longevity, heart health, and cognitive function. The best diet is one you can sustain.'},{q:'Is keto safe long term?',a:'Short-term keto is safe for most people. Long-term effects are less studied. It requires careful micronutrient management.'},{q:'Do I need to count macros?',a:'Only if you have specific body composition goals. Most people do well focusing on food quality rather than precise tracking.'},{q:'What is the difference between low carb and keto?',a:'Low carb typically means under 100g carbs/day. Keto is much stricter at under 20-50g to maintain ketosis.'},{q:'Is plant-based the same as vegan?',a:'Not exactly. Plant-based emphasizes plants as the majority but may include small amounts of animal products. Vegan excludes all animal products.'}],
    related:['calorie-calculator','macro-calculator','keto-calculator','intermittent-fasting-calculator']
  },

  { slug:'fiber-score-calculator', name:'Fiber Intake Score', desc:'Calculate your daily fiber intake and see if you are meeting recommended guidelines.', icon:'food', category:'Nutrition',
    fields:[{id:'fruits',label:'Fruit Servings per Day',type:'number',ph:'2'},{id:'veggies',label:'Vegetable Servings per Day',type:'number',ph:'3'},{id:'grains',label:'Whole Grain Servings per Day',type:'number',ph:'2'},{id:'legumes',label:'Beans/Lentils (times/week)',type:'number',ph:'2'},{id:'nuts',label:'Nuts/Seeds (handful/day)',type:'number',ph:'1'}],
    logic:`var fr=parseFloat(document.getElementById('fruits').value)||0;var vg=parseFloat(document.getElementById('veggies').value)||0;var gr=parseFloat(document.getElementById('grains').value)||0;var lg=parseFloat(document.getElementById('legumes').value)||0;var nt=parseFloat(document.getElementById('nuts').value)||0;var total=Math.round(fr*2.5+vg*2.5+gr*3+lg*2+nt*2);var rec=30;var pct=Math.min(100,Math.round(total/rec*100));var c=total>=rec?'green':total>=rec*0.7?'yellow':'red';var l=total>=rec?'Meeting Goals':total>=rec*0.7?'Almost There':'Below Target';showResult('result',total+'g/day',l+'  ('+pct+'% of '+rec+'g target)','Most adults get only 15g/day vs the recommended 25-38g. '+(total<rec?'Increase legumes (highest fiber), add a handful of nuts, swap refined grains for whole grains, and load up on vegetables.':'Excellent! Your fiber intake supports digestive health, blood sugar control, and cardiovascular health.'),'green');`,
    article:`<h2>Fiber Intake Score Calculator</h2><p>Dietary fiber is one of the most consistently beneficial components of the human diet, yet most people consume barely half the recommended amount. Adequate fiber is linked to reduced risk of colorectal cancer, heart disease, type 2 diabetes, and all-cause mortality. It feeds beneficial gut bacteria, supports bowel regularity, and helps maintain healthy weight through improved satiety.</p>`,
    faqs:[{q:'How much fiber do I need per day?',a:'25g for women, 38g for men (by age 50). Most adults consume only 15-17g daily.'},{q:'What is the best fiber source?',a:'Legumes (beans, lentils) are the highest-fiber foods. Vegetables, fruits, whole grains, and nuts are also excellent sources.'},{q:'Is there such a thing as too much fiber?',a:'Sudden large increases can cause bloating and gas. Gradually increase intake and drink plenty of water.'},{q:'What is the difference between soluble and insoluble fiber?',a:'Soluble fiber (oats, legumes, apples) dissolves in water and lowers cholesterol. Insoluble fiber (bran, vegetables) adds bulk to stool.'},{q:'Can fiber supplements replace food fiber?',a:'Supplements like psyllium husk help but lack the micronutrients and prebiotics from whole food fiber sources.'}],
    related:['calorie-calculator','sugar-intake-calculator','diet-comparison-calculator','water-intake-calculator']
  },

  // ─── GROUP 6: PREGNANCY & SPECIAL POPULATIONS ──────────────────────────────

  { slug:'pregnancy-week-calculator', name:'Pregnancy Week Calculator', desc:'Calculate exactly how many weeks pregnant you are and your estimated due date.', icon:'baby', category:"Women's Health",
    fields:[{id:'lmp',label:'First Day of Last Menstrual Period',type:'date'},{id:'cycle',label:'Average Cycle Length (days)',type:'number',ph:'28'}],
    logic:`var lmp=new Date(document.getElementById('lmp').value);var cyc=parseFloat(document.getElementById('cycle').value)||28;if(!document.getElementById('lmp').value){alert('Enter your LMP date');return;}var adj=cyc-28;var conception=new Date(lmp.getTime()+((14+adj)*86400000));var dueDate=new Date(lmp.getTime()+((280+adj)*86400000));var now=new Date();var diffDays=Math.floor((now-lmp)/86400000);var weeks=Math.floor(diffDays/7);var days=diffDays%7;var tri=weeks<13?'1st':weeks<27?'2nd':'3rd';var daysLeft=Math.max(0,Math.floor((dueDate-now)/86400000));var months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];var dueFmt=months[dueDate.getMonth()]+' '+dueDate.getDate()+', '+dueDate.getFullYear();showResult('result',weeks+' weeks '+days+' days',tri+' Trimester','Estimated due date: '+dueFmt+' | Days remaining: '+daysLeft+' | Trimester: '+tri+'. At week '+weeks+': baby is about '+Math.round(weeks*2.5)+'mm long. Always confirm with your healthcare provider via ultrasound.','green');`,
    article:`<h2>Pregnancy Week Calculator</h2><p>Knowing exactly how far along you are in your pregnancy helps you track your baby's development, prepare for prenatal appointments, and understand what to expect at each stage. Pregnancy is divided into three trimesters, each with distinct developmental milestones and maternal changes.</p><h3>How Pregnancy Weeks Are Counted</h3><p>Pregnancy is calculated from the first day of your last menstrual period (LMP), even though conception typically occurs about 2 weeks later. This means a 40-week full-term pregnancy includes approximately 38 weeks of actual fetal development. Most pregnancies deliver between 37 and 42 weeks.</p>`,
    faqs:[{q:'How many weeks is a full-term pregnancy?',a:'Full term is 37-42 weeks. 39-40 weeks is considered the optimal timing for most babies.'},{q:'What if my cycle is longer than 28 days?',a:'Our calculator adjusts for cycle length. A 35-day cycle shifts ovulation and estimated due date by 7 days.'},{q:'How accurate is the due date calculation?',a:'Only 4% of babies are born on their exact due date. Most arrive within 2 weeks before or after.'},{q:'When does each trimester start?',a:'First: weeks 1-12. Second: weeks 13-26. Third: weeks 27-40.'},{q:'How does ultrasound due date differ?',a:'Early ultrasound (8-12 weeks) is the most accurate dating method and may adjust the LMP-based estimate slightly.'}],
    related:['pregnancy-due-date-calculator','pregnancy-weight-gain-calculator','baby-weight-calculator','breastfeeding-calorie-calculator']
  },

  { slug:'hydration-level-calculator', name:'Hydration Level Calculator', desc:'Assess your hydration status and calculate optimal daily water intake for your lifestyle.', icon:'water', category:'Nutrition',
    fields:[{id:'weight',label:'Body Weight (kg)',type:'number',ph:'75'},{id:'activity',label:'Activity Level',type:'select',options:['Sedentary','Lightly Active','Moderately Active','Very Active']},{id:'climate',label:'Climate/Environment',type:'select',options:['Cool/Temperate','Warm','Hot/Humid']},{id:'symptoms',label:'Current Symptoms',type:'select',options:['None','Mild thirst','Noticeable thirst + yellow urine','Headache + concentrated urine','Very dark urine + dizziness']}],
    logic:`var w=parseFloat(document.getElementById('weight').value);var act=document.getElementById('activity').value;var clim=document.getElementById('climate').value;var sym=document.getElementById('symptoms').value;if(!w){alert('Enter weight');return;}var base=w*35/1000;var actAdd={'Sedentary':0,'Lightly Active':0.3,'Moderately Active':0.5,'Very Active':0.8}[act]||0;var climAdd={'Cool/Temperate':0,'Warm':0.3,'Hot/Humid':0.5}[clim]||0;var total=(base+actAdd+climAdd).toFixed(1);var status={'None':'Well Hydrated','Mild thirst':'Slightly Low','Noticeable thirst + yellow urine':'Dehydrated','Headache + concentrated urine':'Significantly Dehydrated','Very dark urine + dizziness':'Severely Dehydrated'}[sym]||'Unknown';var c={'None':'green','Mild thirst':'yellow','Noticeable thirst + yellow urine':'yellow','Headache + concentrated urine':'red','Very dark urine + dizziness':'red'}[sym]||'green';showResult('result',total+' L/day','Daily Water Target | Status: '+status,'Recommendation: drink '+total+' liters throughout the day. Dehydration status: '+status+'. Best hydration check: urine should be pale yellow, not dark. Divide intake across 6-8 sessions throughout the day.',c);`,
    article:`<h2>Hydration Level Calculator</h2><p>Water makes up 60% of the adult body and is involved in every biological process — from nutrient transport to temperature regulation to joint lubrication. Even mild dehydration (1-2% of body weight) measurably impairs cognitive function, physical performance, and mood. The old "8 glasses per day" rule is a simplification; actual needs vary significantly by weight, activity, climate, and health status.</p>`,
    faqs:[{q:'How much water should I drink per day?',a:'General guideline is 35ml per kg of body weight, increased by activity level and climate. Our calculator provides a personalized target.'},{q:'Does coffee or tea count toward hydration?',a:'Yes. Despite mild diuretic effects, caffeinated beverages still contribute net hydration. Only avoid counting if consuming very large amounts.'},{q:'What is the best way to assess hydration?',a:'Urine color is the most practical test. Pale yellow (like lemonade) = good hydration. Dark yellow or amber = drink more water.'},{q:'Can you drink too much water?',a:'Yes, hyponatremia (water intoxication) can occur from extreme over-hydration, primarily a risk for endurance athletes. Thirst is generally a reliable guide.'},{q:'Do foods count toward water intake?',a:'Yes. Fruits and vegetables can contribute 20-30% of daily hydration needs. Cucumber, watermelon, and celery are over 90% water.'}],
    related:['water-intake-calculator','electrolyte-calculator','sodium-intake-calculator','bmi-calculator']
  },

  // ─── GROUP 7: GENERAL HEALTH TOOLS ─────────────────────────────────────────

  { slug:'testosterone-estimator', name:'Testosterone Level Estimator', desc:'Estimate your testosterone range based on age and lifestyle factors (informational only).', icon:'heart', category:'Health Risk',
    fields:[{id:'age',label:'Age',type:'number',ph:'35'},{id:'exercise',label:'Strength Training (days/week)',type:'number',ph:'3'},{id:'sleep',label:'Average Sleep (hours)',type:'number',ph:'7'},{id:'stress',label:'Stress Level (1-5)',type:'number',ph:'3'},{id:'bmi',label:'BMI Category',type:'select',options:['Normal Weight','Overweight','Obese']},{id:'alcohol',label:'Alcohol Intake',type:'select',options:['None','Moderate (1-7 drinks/week)','Heavy (8+ drinks/week)']}],
    logic:`var age=parseFloat(document.getElementById('age').value)||35;var ex=parseFloat(document.getElementById('exercise').value)||0;var sl=parseFloat(document.getElementById('sleep').value)||7;var st=parseFloat(document.getElementById('stress').value)||3;var bmi=document.getElementById('bmi').value;var alc=document.getElementById('alcohol').value;var base=age<30?650:age<40?550:age<50?480:age<60?420:360;if(ex>=4)base+=80;else if(ex>=2)base+=40;if(sl>=7&&sl<=9)base+=50;else if(sl<6)base-=80;if(st<=2)base+=30;else if(st>=4)base-=60;if(bmi==='Overweight')base-=50;if(bmi==='Obese')base-=120;if(alc==='Heavy (8+ drinks/week)')base-=100;base=Math.max(150,Math.min(900,Math.round(base)));var c=base>=400?'green':base>=300?'yellow':'red';var l=base>=400?'Normal Range':base>=300?'Low-Normal':'Potentially Low';showResult('result','~'+base+' ng/dL',l,'Estimated range for age '+age+'. Normal adult male range: 300-1000 ng/dL. '+l+' based on your inputs. Lifestyle factors (exercise, sleep, stress, weight, alcohol) significantly impact testosterone. For accurate measurement, get a morning blood test. This is NOT a medical diagnosis.',c);`,
    article:`<h2>Testosterone Level Estimator</h2><p>Testosterone is the primary male sex hormone, though women also need it in smaller amounts. In men, it peaks in the late teens and declines about 1-2% per year after age 30. Low testosterone (hypogonadism) affects an estimated 10-40% of men over 45 and is associated with fatigue, reduced muscle mass, low libido, mood changes, and cognitive decline.</p><h3>Lifestyle Factors That Affect Testosterone</h3><p>Resistance training (especially compound lifts), adequate sleep (7-9 hours), stress management, maintaining healthy body weight, and limiting alcohol consumption all support healthy testosterone levels. Conversely, chronic stress, obesity, poor sleep, excessive alcohol, and sedentary behavior significantly suppress testosterone production.</p><p><strong>Important:</strong> This estimator is for informational purposes. Only a blood test (preferably a morning sample) provides an accurate testosterone measurement.</p>`,
    faqs:[{q:'What is the normal testosterone range?',a:'For adult men: 300-1000 ng/dL. Most laboratories consider below 300 ng/dL as low (hypogonadism).'},{q:'What are symptoms of low testosterone?',a:'Fatigue, low libido, reduced muscle mass, increased body fat, mood changes (irritability, depression), and reduced bone density.'},{q:'How can I naturally boost testosterone?',a:'Compound resistance training, adequate sleep (7-9h), stress reduction, maintaining healthy weight, zinc/vitamin D sufficiency, and limiting alcohol.'},{q:'Does testosterone replacement therapy work?',a:'TRT is effective for clinically low testosterone but has side effects. It requires medical supervision and is not appropriate for everyone.'},{q:'Does age affect testosterone?',a:'Yes, levels decline 1-2% per year after 30. By 70, most men have 30-50% lower testosterone than at peak levels.'}],
    related:['biological-age-calculator','stress-level-calculator','body-fat-calculator','heart-age-calculator']
  },

  { slug:'anti-inflammatory-score', name:'Anti-Inflammatory Diet Score', desc:'Score your diet for anti-inflammatory potential and get guidance to reduce chronic inflammation.', icon:'food', category:'Nutrition',
    fields:[{id:'omega3',label:'Omega-3 Fish 2+ times/week?',type:'select',options:['Yes','No']},{id:'veggies',label:'5+ Veggies/Fruits Per Day?',type:'select',options:['Yes','No']},{id:'olive',label:'Use Olive Oil as Primary Fat?',type:'select',options:['Yes','No']},{id:'sugar',label:'Low Added Sugar (<25g/day)?',type:'select',options:['Yes','No']},{id:'refined',label:'Avoid Refined Grains?',type:'select',options:['Yes','No']},{id:'spice',label:'Use Anti-Inflammatory Spices (turmeric, ginger)?',type:'select',options:['Yes','No']},{id:'alcohol',label:'Alcohol < 1 drink/day?',type:'select',options:['Yes','No']}],
    logic:`var yes=function(id){return document.getElementById(id).value==='Yes'?1:0;};var score=yes('omega3')+yes('veggies')+yes('olive')+yes('sugar')+yes('refined')+yes('spice')+yes('alcohol');var pct=Math.round(score/7*100);var c=score>=5?'green':score>=3?'yellow':'red';var l=score>=5?'Anti-Inflammatory Diet':score>=3?'Moderately Inflammatory':'Pro-Inflammatory';var tips=[];if(!yes('omega3'))tips.push('Add fatty fish 2x/week');if(!yes('veggies'))tips.push('Aim for 5+ fruits/veggies daily');if(!yes('olive'))tips.push('Switch to olive oil');if(!yes('sugar'))tips.push('Reduce added sugar');var tipStr=tips.length?'Priorities: '+tips.join(', ')+'.':'Excellent anti-inflammatory diet!';showResult('result',score+'/7',l,'Anti-inflammatory score: '+pct+'%. Chronic inflammation drives heart disease, diabetes, cancer, and Alzheimer\'s. '+tipStr,c);`,
    article:`<h2>Anti-Inflammatory Diet Score</h2><p>Chronic low-grade inflammation is increasingly recognized as a root driver of most major diseases — heart disease, type 2 diabetes, cancer, Alzheimer's, and autoimmune conditions. Diet is one of the most powerful tools to modulate inflammatory status. Anti-inflammatory eating focuses on omega-3 fatty acids, polyphenol-rich plants, fiber, and minimizing refined carbohydrates, trans fats, and excess sugar.</p>`,
    faqs:[{q:'What foods cause inflammation?',a:'Refined carbohydrates, sugar, trans fats, processed meats, excessive saturated fats, and alcohol are the primary pro-inflammatory foods.'},{q:'What foods reduce inflammation?',a:'Fatty fish (omega-3), olive oil, berries, leafy greens, turmeric, ginger, nuts, and cruciferous vegetables are top anti-inflammatory foods.'},{q:'Does the Mediterranean diet reduce inflammation?',a:'Yes. The Mediterranean diet consistently reduces inflammatory markers (CRP, IL-6) in clinical studies — it is the gold standard anti-inflammatory diet.'},{q:'Can an anti-inflammatory diet cure autoimmune disease?',a:'Diet helps manage symptoms and may reduce flares, but is not a cure. It works alongside conventional medical treatment.'},{q:'How quickly does diet affect inflammation?',a:'Measurable reductions in inflammatory markers can occur within 2-6 weeks of consistent dietary changes.'}],
    related:['omega3-calculator','sugar-intake-calculator','diet-comparison-calculator','cholesterol-risk-calculator']
  },

  { slug:'work-life-balance-calculator', name:'Work-Life Balance Calculator', desc:'Assess your work-life balance and get personalized strategies for improvement.', icon:'brain', category:'Mental Health',
    fields:[{id:'workhours',label:'Work Hours Per Week',type:'number',ph:'45'},{id:'commute',label:'Daily Commute (minutes each way)',type:'number',ph:'30'},{id:'vacation',label:'Vacation Days Per Year',type:'number',ph:'14'},{id:'exercise',label:'Exercise Hours Per Week',type:'number',ph:'3'},{id:'social',label:'Social/Family Time (hours/week)',type:'number',ph:'10'},{id:'sleep',label:'Average Sleep Per Night (hours)',type:'number',ph:'7'}],
    logic:`var work=parseFloat(document.getElementById('workhours').value)||45;var comm=parseFloat(document.getElementById('commute').value)||30;var vac=parseFloat(document.getElementById('vacation').value)||14;var ex=parseFloat(document.getElementById('exercise').value)||3;var soc=parseFloat(document.getElementById('social').value)||10;var sl=parseFloat(document.getElementById('sleep').value)||7;var totalWorkTime=work+(comm*2*5/60);var totalPersonal=168-totalWorkTime-(sl*7);var score=0;if(work<=40)score+=20;else if(work<=50)score+=10;if(vac>=20)score+=15;else if(vac>=10)score+=8;if(ex>=3)score+=15;else if(ex>=1)score+=8;if(soc>=15)score+=15;else if(soc>=8)score+=8;if(sl>=7&&sl<=9)score+=15;else if(sl>=6)score+=8;if(comm<=30)score+=10;var c=score>=70?'green':score>=45?'yellow':'red';var l=score>=70?'Healthy Balance':score>=45?'Moderate Imbalance':'Poor Balance';showResult('result',score+'/90',l,'Work time/week: ~'+Math.round(totalWorkTime)+' hrs. Personal time: ~'+Math.round(totalPersonal)+' hrs. '+(work>50?'Working over 50 hrs/week significantly raises burnout, cardiovascular disease, and mental health risks. ':'')+( sl<7?'Sleep is below optimal — this is the highest leverage improvement you can make. ':'')+( ex<2?'Adding exercise (even 30 min/day) is the single biggest wellbeing investment. ':''),c);`,
    article:`<h2>Work-Life Balance Calculator</h2><p>Work-life balance describes the equilibrium between professional responsibilities and personal wellbeing — including rest, relationships, health, and leisure. Chronic imbalance, particularly overwork, is associated with burnout, cardiovascular disease, depression, relationship breakdown, and reduced longevity. The WHO lists overwork as a serious occupational health risk.</p>`,
    faqs:[{q:'How many hours per week is healthy to work?',a:'Research consistently shows performance peaks around 40-50 hours per week. Above 55 hours, productivity per hour drops sharply and health risks rise.'},{q:'Does remote work improve work-life balance?',a:'It can, but requires intentional boundaries. Without clear start/end times, remote work often leads to longer hours and blurred boundaries.'},{q:'How does vacation affect health?',a:'Taking all annual leave reduces heart attack risk by 30%. Unused vacation days do not provide health benefits.'},{q:'What is the most important work-life balance change?',a:'Sleep. It affects everything else — energy, decision-making, relationships, and resilience. Non-negotiably protect 7-9 hours.'},{q:'Can exercise offset the effects of overwork?',a:'Regular exercise mitigates some negative effects of sedentary work, but does not fully compensate for chronic overwork and social isolation.'}],
    related:['burnout-risk-calculator','stress-level-calculator','sleep-hygiene-calculator','productivity-score-calculator']
  },

  { slug:'child-growth-calculator', name:'Child Growth Calculator', desc:'Assess child height and weight percentiles for ages 2-17 using CDC growth standards.', icon:'baby', category:"Women's Health",
    fields:[{id:'age',label:'Child Age (years)',type:'number',ph:'8'},{id:'gender',label:'Gender',type:'select',options:['Boy','Girl']},{id:'height',label:'Height (cm)',type:'number',ph:'128'},{id:'weight',label:'Weight (kg)',type:'number',ph:'28'}],
    logic:`var age=parseFloat(document.getElementById('age').value);var g=document.getElementById('gender').value;var h=parseFloat(document.getElementById('height').value);var w=parseFloat(document.getElementById('weight').value);if(!age||!h||!w||age<2||age>18){alert('Enter valid values (age 2-18)');return;}var bmi=w/Math.pow(h/100,2);var avgh=g==='Boy'?100+age*6.5:100+age*6.2;var avgw=g==='Boy'?Math.pow(age,1.6)*2:Math.pow(age,1.55)*2;var hpct=Math.min(99,Math.max(1,Math.round(50+(h-avgh)/3)));var wpct=Math.min(99,Math.max(1,Math.round(50+(w-avgw)/2)));var c=bmi<14||bmi>28?'yellow':'green';showResult('result','BMI: '+bmi.toFixed(1),'Estimated Growth Percentiles','Height: ~'+hpct+'th percentile | Weight: ~'+wpct+'th percentile | BMI: '+bmi.toFixed(1)+'. Note: These are rough estimates. For accurate percentile assessment, use official CDC charts or consult your pediatrician. BMI interpretation for children uses age-specific percentiles, not adult ranges.','green');`,
    article:`<h2>Child Growth Calculator</h2><p>Monitoring a child's growth is one of the most important aspects of pediatric health assessment. Children grow at different rates, and what matters most is consistent growth along their personal curve — not reaching a specific percentile. Sudden changes in growth trajectory are more concerning than being at a low percentile.</p><h3>Understanding Percentiles</h3><p>A height at the 25th percentile means 25% of children the same age and gender are shorter, and 75% are taller. Most children are "normal" anywhere from the 3rd to 97th percentile — the concern is rapid crossing of major percentile lines. Pediatricians typically evaluate growth at each well-child visit.</p>`,
    faqs:[{q:'What is a normal growth percentile?',a:'The 3rd to 97th percentile is considered normal. What matters most is consistent growth along the child\'s personal curve.'},{q:'Why is my child\'s BMI interpreted differently than adults?',a:'Children\'s BMI must account for age and sex, as body composition changes significantly through childhood. Adult cutoffs do not apply.'},{q:'How accurate are online growth calculators?',a:'Online calculators provide rough estimates. For accurate assessment, use official CDC percentile charts or consult your pediatrician.'},{q:'When should I be concerned about my child\'s growth?',a:'If your child drops 2 or more major percentile lines (e.g., 75th to 25th), crosses the 3rd or 97th percentile, or their growth velocity slows significantly.'},{q:'Does nutrition affect a child\'s height?',a:'Yes, especially in the first 5 years. Adequate protein, calories, calcium, vitamin D, and zinc are critical for achieving full height potential.'}],
    related:['bmi-calculator','child-bmi-calculator','baby-weight-calculator','calorie-calculator']
  },

  // ─── GROUP 8: TIMING & CONVENIENCE TOOLS ───────────────────────────────────

  { slug:'intermittent-fasting-window', name:'Fasting Window Calculator', desc:'Calculate your eating and fasting windows for any IF protocol with start/end times.', icon:'food', category:'Nutrition',
    fields:[{id:'protocol',label:'Fasting Protocol',type:'select',options:['12:12','14:10','16:8','18:6','20:4','OMAD (23:1)']},{id:'wakeup',label:'Wake-Up Time',type:'time'},{id:'pref',label:'Preference',type:'select',options:['Eat Earlier (skip dinner)','Eat Later (skip breakfast)','Midday Window']}],
    logic:`var proto=document.getElementById('protocol').value;var wake=document.getElementById('wakeup').value;var pref=document.getElementById('pref').value;if(!wake){alert('Enter wake-up time');return;}var hours={'12:12':12,'14:10':10,'16:8':8,'18:6':6,'20:4':4,'OMAD (23:1)':1}[proto]||8;var fastH=24-hours;var wh=parseInt(wake.split(':')[0]);var wm=parseInt(wake.split(':')[1]);var startH,endH;if(pref==='Eat Earlier (skip dinner)'){startH=wh+1;}else if(pref==='Eat Later (skip breakfast)'){startH=wh+fastH-8;}else{startH=wh+Math.floor(fastH/2);}startH=startH%24;endH=(startH+hours)%24;var fmt=function(h,m){return (h%12||12)+':'+(m<10?'0':'')+m+' '+(h<12?'AM':'PM');};var sm=wm;showResult('result',proto+' Protocol','Your Fasting Schedule','Eating window: '+fmt(startH,sm)+' to '+fmt(endH,sm)+' ('+hours+' hours). Fasting window: '+fastH+' hours. During fasting: water, black coffee, plain tea, and sparkling water are allowed. Break your fast with a protein-rich meal.','green');`,
    article:`<h2>Fasting Window Calculator</h2><p>Intermittent fasting (IF) is an eating pattern that cycles between periods of eating and fasting. Unlike traditional diets, IF focuses on when you eat, not just what you eat. The most popular protocol is 16:8 (16 hours fasting, 8 hours eating), but options range from the gentle 12:12 to the extreme OMAD (one meal a day).</p>`,
    faqs:[{q:'What can I consume during fasting?',a:'Water, plain sparkling water, black coffee, and unsweetened plain tea are generally considered fasting-safe as they do not trigger insulin.'},{q:'Which IF protocol is best for beginners?',a:'Start with 12:12 (finish dinner by 8pm, breakfast at 8am). Once comfortable, try 14:10, then 16:8.'},{q:'Does IF cause muscle loss?',a:'Short-term IF (16:8) with adequate protein does not cause significant muscle loss. Ensure sufficient daily protein intake.'},{q:'Can women do intermittent fasting?',a:'Yes, but some women find strict IF disrupts hormones. A gentler approach (14:10) is often better tolerated by women.'},{q:'Should I fast every day?',a:'Daily IF (like 16:8) is sustainable for most people. Alternate day fasting or 5:2 involves more extreme fasting days.'}],
    related:['intermittent-fasting-calculator','calorie-calculator','sugar-intake-calculator','diet-comparison-calculator']
  },

  { slug:'calorie-burn-calculator', name:'Activity Calorie Burn Calculator', desc:'Calculate calories burned for 40+ common activities based on your weight and duration.', icon:'fitness', category:'Fitness',
    fields:[{id:'weight',label:'Body Weight (kg)',type:'number',ph:'75'},{id:'activity',label:'Activity',type:'select',options:['Walking (moderate)','Running (8 km/h)','Running (12 km/h)','Cycling (moderate)','Swimming','HIIT Training','Weight Training','Yoga','Pilates','Dancing','Hiking','Rowing','Jump Rope','Basketball','Tennis','Golf','Gardening','Cleaning House','Cooking','Office Work']},{id:'duration',label:'Duration (minutes)',type:'number',ph:'30'}],
    logic:`var w=parseFloat(document.getElementById('weight').value);var act=document.getElementById('activity').value;var dur=parseFloat(document.getElementById('duration').value);if(!w||!dur){alert('Fill all fields');return;}var mets={'Walking (moderate)':3.5,'Running (8 km/h)':8.3,'Running (12 km/h)':11.8,'Cycling (moderate)':6.8,'Swimming':7,'HIIT Training':12,'Weight Training':4,'Yoga':2.5,'Pilates':3,'Dancing':5,'Hiking':6,'Rowing':7,'Jump Rope':11,'Basketball':8,'Tennis':7.3,'Golf':4,'Gardening':4,'Cleaning House':3.5,'Cooking':2.5,'Office Work':1.5};var met=mets[act]||4;var cal=Math.round(met*w*dur/60);showResult('result',cal+' kcal','Calories Burned: '+act,'You burned approximately '+cal+' calories during '+dur+' minutes of '+act+'. Rate: '+Math.round(cal/(dur/60))+' kcal/hour. For weight loss, combine activity with a moderate calorie deficit.','green');`,
    article:`<h2>Activity Calorie Burn Calculator</h2><p>Different activities burn dramatically different numbers of calories. Understanding your calorie burn helps you plan workouts, track activity energy expenditure, and make informed decisions about nutrition. Our calculator uses MET (Metabolic Equivalent of Task) values — a standardized system for measuring exercise intensity used by exercise physiologists worldwide.</p>`,
    faqs:[{q:'How accurate are calorie burn calculators?',a:'Within 10-20% for most people. Individual variation in efficiency, fitness level, and muscle mass affects actual burn.'},{q:'What is a MET value?',a:'MET (Metabolic Equivalent of Task) is a ratio of exercise energy expenditure to resting metabolism. Walking has a MET of 3-4; running 8-12.'},{q:'Does weight affect calories burned?',a:'Yes. Heavier people burn more calories doing the same activity because moving greater mass requires more energy.'},{q:'Is NEAT important for calorie burn?',a:'NEAT (Non-Exercise Activity Thermogenesis) — fidgeting, walking, standing — can account for 300-700 extra calories daily in active people.'},{q:'Which activity burns the most calories?',a:'Per hour: running, jump rope, rowing, and HIIT top the list. Per minute of effort: HIIT is most time-efficient.'}],
    related:['steps-to-calories-calculator','hiit-calories-calculator','calorie-calculator','running-pace-calculator']
  },

  { slug:'pomodoro-calculator', name:'Pomodoro Productivity Calculator', desc:'Calculate optimal Pomodoro sessions for your task list and work schedule.', icon:'brain', category:'Mental Health',
    fields:[{id:'tasks',label:'Number of Tasks Today',type:'number',ph:'5'},{id:'pomodoros',label:'Estimated Pomodoros Per Task (avg)',type:'number',ph:'2'},{id:'workstart',label:'Work Start Time',type:'time'},{id:'breaktype',label:'Break Style',type:'select',options:['Classic (25/5/15)','Extended (50/10/30)','Short (15/3/10)']}],
    logic:`var tasks=parseFloat(document.getElementById('tasks').value)||5;var poms=parseFloat(document.getElementById('pomodoros').value)||2;var start=document.getElementById('workstart').value||'09:00';var btype=document.getElementById('breaktype').value;var work=btype==='Classic (25/5/15)'?25:btype==='Extended (50/10/30)'?50:15;var shortBk=btype==='Classic (25/5/15)'?5:btype==='Extended (50/10/30)'?10:3;var longBk=btype==='Classic (25/5/15)'?15:btype==='Extended (50/10/30)'?30:10;var total=tasks*poms;var cycles=Math.floor(total/4);var rem=total%4;var totalMin=total*work+cycles*longBk+rem*shortBk;var sh=parseInt(start.split(':')[0]);var sm=parseInt(start.split(':')[1]);var endH=Math.floor((sh*60+sm+totalMin)/60)%24;var endM=(sm+totalMin)%60;showResult('result',total+' pomodoros','Work Session Plan','Tasks: '+tasks+' | Total pomodoros: '+total+' | Estimated finish: '+((endH%12)||12)+':'+(endM<10?'0':'')+endM+' '+(endH<12?'AM':'PM')+'. Long breaks: '+cycles+'. Remember: during each pomodoro, work on ONLY that task with zero interruptions.','green');`,
    article:`<h2>Pomodoro Calculator</h2><p>The Pomodoro Technique, developed by Francesco Cirillo in the 1980s, breaks work into focused intervals (traditionally 25 minutes) separated by short breaks. Research confirms that this structured approach reduces mental fatigue, combats procrastination, and improves awareness of how long tasks actually take. The technique is named after a tomato-shaped kitchen timer Cirillo used as a university student.</p>`,
    faqs:[{q:'What is the Pomodoro Technique?',a:'A time management method using 25-minute focused work intervals followed by 5-minute breaks, with a longer break after every 4 sessions.'},{q:'Can I adjust the Pomodoro duration?',a:'Yes. The 25-minute interval works best for most people, but some prefer 45-50 minute focus blocks with longer breaks.'},{q:'What counts as interrupting a Pomodoro?',a:'Any task-switching, phone checking, or unplanned conversation interrupts the Pomodoro. Record interruptions and restart if they occur.'},{q:'Does the Pomodoro technique work for creative work?',a:'Yes, though creative flow states can sometimes be disrupted by the 25-minute limit. Try longer 50-90 minute blocks for deep creative work.'},{q:'How many Pomodoros can I do in a day?',a:'Most people can do 8-12 quality Pomodoros per day. Attempting more often leads to diminishing quality.'}],
    related:['focus-score-calculator','productivity-score-calculator','countdown-timer','burnout-risk-calculator']
  },

  { slug:'age-in-days-calculator', name:'Age in Days Calculator', desc:'Calculate your exact age in days, hours, minutes, and even seconds.', icon:'body', category:'General',
    fields:[{id:'dob',label:'Date of Birth',type:'date'},{id:'unit',label:'Display In',type:'select',options:['Days','Hours','Minutes','Weeks & Days']}],
    logic:`var dob=new Date(document.getElementById('dob').value);if(!document.getElementById('dob').value){alert('Enter date of birth');return;}var now=new Date();var ms=now-dob;var days=Math.floor(ms/86400000);var hours=Math.floor(ms/3600000);var minutes=Math.floor(ms/60000);var weeks=Math.floor(days/7);var remDays=days%7;var unit=document.getElementById('unit').value;var val,label;if(unit==='Days'){val=days.toLocaleString();label='Days Old';}else if(unit==='Hours'){val=hours.toLocaleString();label='Hours Old';}else if(unit==='Minutes'){val=minutes.toLocaleString();label='Minutes Old';}else{val=weeks.toLocaleString()+' wk '+remDays+'d';label='Weeks + Days Old';}showResult('result',val,label,'You have lived approximately '+days.toLocaleString()+' days ('+hours.toLocaleString()+' hours | '+minutes.toLocaleString()+' minutes). Heart beats so far: ~'+Math.round(days*100000).toLocaleString()+'. Breaths taken: ~'+Math.round(days*23040).toLocaleString()+'.','green');`,
    article:`<h2>Age in Days Calculator</h2><p>Ever wondered exactly how many days you have been alive? Our Age in Days Calculator gives you your life span in days, hours, minutes, and weeks — along with fascinating statistics about your biological activity during that time. It is a fun way to appreciate the remarkable length of your journey so far.</p>`,
    faqs:[{q:'How many days old is a 30-year-old?',a:'Approximately 10,950-10,960 days, depending on exact birth date and leap years.'},{q:'How many hours in a year?',a:'Exactly 8,760 hours in a regular year, and 8,784 in a leap year.'},{q:'How many times has my heart beaten?',a:'The heart beats about 100,000 times per day. Multiply your day count by 100,000 for an approximate lifetime count.'},{q:'How long has a 100-year-old lived in days?',a:'About 36,524 days (accounting for 25 leap years in a century).'},{q:'Why is the calculation not perfectly precise?',a:'Timezone differences between birth location and current location can affect the exact count by a few hours.'}],
    related:['age-calculator','birthday-calculator','date-difference-calculator']
  },

  { slug:'bmi-prime-calculator', name:'BMI Prime Calculator', desc:'Calculate your BMI Prime — a refined BMI measure showing how you compare to the upper healthy limit.', icon:'body', category:'Body Metrics',
    fields:[{id:'weight',label:'Weight (kg)',type:'number',ph:'75'},{id:'height',label:'Height (cm)',type:'number',ph:'170'}],
    logic:`var w=parseFloat(document.getElementById('weight').value);var h=parseFloat(document.getElementById('height').value)/100;if(!w||!h){alert('Fill all fields');return;}var bmi=w/(h*h);var bmiPrime=(bmi/25).toFixed(2);var c=bmiPrime<=1.0?'green':bmiPrime<=1.2?'yellow':'red';var l=bmiPrime<0.74?'Underweight':bmiPrime<=1.0?'Optimal':bmiPrime<=1.2?'Overweight':'Obese';showResult('result',bmiPrime,'BMI Prime','BMI: '+bmi.toFixed(1)+' | BMI Prime: '+bmiPrime+'. A BMI Prime of 1.0 means your BMI exactly equals the upper healthy limit (25). Values below 1.0 are healthy; above 1.0 indicates excess weight. This measure makes it easy to see how far from optimal your weight is.','green');`,
    faqs:[{q:'What is BMI Prime?',a:'BMI Prime is your BMI divided by 25 (the upper healthy BMI limit). A value of 1.0 is perfectly at the healthy limit.'},{q:'How is BMI Prime better than regular BMI?',a:'BMI Prime makes it intuitive: a value of 1.2 means you are 20% above the upper healthy limit, regardless of exact BMI numbers.'},{q:'What is the healthy BMI Prime range?',a:'0.74 to 1.00 (corresponding to BMI 18.5-25) is considered the healthy range.'},{q:'Does BMI Prime have the same limitations as BMI?',a:'Yes. Like BMI, it does not distinguish between fat and muscle and may not accurately reflect health for all body types.'},{q:'Who developed BMI Prime?',a:'BMI Prime was proposed by fitness expert Nick Trefethen as a clearer way to communicate BMI-based weight status.'}],
    related:['bmi-calculator','ideal-weight-calculator','body-fat-calculator','waist-to-hip-ratio']
  },

  { slug:'lean-mass-goal-calculator', name:'Lean Mass Goal Calculator', desc:'Calculate how much muscle you need to gain to reach your ideal body composition.', icon:'body', category:'Body Metrics',
    fields:[{id:'weight',label:'Current Weight (kg)',type:'number',ph:'80'},{id:'bodyfat',label:'Current Body Fat (%)',type:'number',ph:'25'},{id:'targetbf',label:'Target Body Fat (%)',type:'number',ph:'15'},{id:'goal',label:'Goal',type:'select',options:['Lose Fat (maintain muscle)','Build Muscle (slight fat gain OK)','Recomposition (simultaneous)']}],
    logic:`var w=parseFloat(document.getElementById('weight').value);var bf=parseFloat(document.getElementById('bodyfat').value);var tbf=parseFloat(document.getElementById('targetbf').value);var goal=document.getElementById('goal').value;if(!w||!bf||!tbf){alert('Fill all fields');return;}var lm=w*(1-bf/100);var fatMass=w-lm;var c=bf>tbf?'green':'yellow';if(goal==='Lose Fat (maintain muscle)'){var targetW=lm/(1-tbf/100);var fatLoss=w-targetW;showResult('result',fatLoss.toFixed(1)+' kg fat loss','Fat Loss Required to Hit '+tbf+'% BF','Current lean mass: '+lm.toFixed(1)+'kg | Target weight: '+targetW.toFixed(1)+'kg | Fat to lose: '+fatLoss.toFixed(1)+'kg. At safe rate of 0.5kg/week, this takes '+Math.round(fatLoss/0.5)+' weeks.',c);}else if(goal==='Build Muscle (slight fat gain OK)'){var muscleNeeded=w*tbf/100-fatMass+lm-lm;var newLM=lm+(fatMass*(tbf/100));showResult('result',lm.toFixed(1)+' kg current lean mass','Muscle Building Target','Current lean mass: '+lm.toFixed(1)+'kg | Fat mass: '+fatMass.toFixed(1)+'kg. At 0.5-1kg muscle/month for naturals, reaching significant composition change takes 6-18 months of consistent training and adequate protein (1.6-2.2g/kg).','green');}else{showResult('result',lm.toFixed(1)+' kg lean mass','Body Recomposition Plan','Recomp works best for beginners and those returning to training. Aim for: 1g+ protein per lb bodyweight, slight calorie deficit (200-300 kcal), progressive resistance training 3-4x/week. Expect slow but simultaneous fat loss and muscle gain.','green');}`,
    article:`<h2>Lean Mass Goal Calculator</h2><p>Body composition transformation comes down to understanding your current ratio of lean mass (muscle, bone, organs) to fat mass, and creating a realistic plan to reach your target. This calculator helps you visualize exactly how much fat to lose or muscle to gain to reach your ideal body fat percentage.</p>`,
    faqs:[{q:'How fast can I build muscle?',a:'Natural muscle gain rates are approximately 0.5-1 kg per month for beginners, slowing to 0.25-0.5 kg per month for intermediates.'},{q:'How fast can I safely lose fat?',a:'0.5-1 kg per week is the safe range. Faster rates risk significant muscle loss along with fat.'},{q:'What is body recomposition?',a:'Simultaneously losing fat and gaining muscle. Possible for beginners, those returning to training, and with anabolic assistance.'},{q:'What body fat percentage is healthy?',a:'Men: 10-20% is fit/healthy. Women: 18-28% is fit/healthy. Elite athletes can go lower but this may not be sustainable.'},{q:'Should I bulk or cut first?',a:'Generally, if above 20% BF (men) or 30% (women), cut first. If lean, a controlled bulk is more appropriate.'}],
    related:['body-fat-calculator','protein-intake-calculator','calorie-calculator','strength-level-calculator']
  },

  { slug:'waist-reduction-calculator', name:'Waist Reduction Calculator', desc:'Calculate how long it will take to reach a healthy waist circumference with realistic projections.', icon:'body', category:'Body Metrics',
    fields:[{id:'current',label:'Current Waist (cm)',type:'number',ph:'95'},{id:'gender',label:'Gender',type:'select',options:['Male','Female']},{id:'target',label:'Target Waist (cm)',type:'number',ph:'80'},{id:'exercise',label:'Cardio Sessions Per Week',type:'number',ph:'3'},{id:'diet',label:'Calorie Deficit Strategy',type:'select',options:['Mild (250 kcal/day)','Moderate (500 kcal/day)','Aggressive (750 kcal/day)']}],
    logic:`var curr=parseFloat(document.getElementById('current').value);var g=document.getElementById('gender').value;var tgt=parseFloat(document.getElementById('target').value);var ex=parseFloat(document.getElementById('exercise').value)||3;var diet=document.getElementById('diet').value;if(!curr||!tgt){alert('Fill all fields');return;}var threshold=g==='Male'?94:80;var reduction=curr-tgt;if(reduction<=0){showResult('result','Already at Goal!','Waist Goal Achieved','Your current waist is at or below your target. Maintain your healthy habits and consider whether a lower target is appropriate.','green');return;}var deficits={'Mild (250 kcal/day)':250,'Moderate (500 kcal/day)':500,'Aggressive (750 kcal/day)':750}[diet]||500;var weeklyFatKg=deficits*7/7700;var cmPerWeek=weeklyFatKg*2.5+(ex*0.3);var weeks=Math.round(reduction/cmPerWeek);showResult('result',weeks+' weeks','Time to Reach Target Waist','Reduction needed: '+reduction+' cm | Weekly loss rate: ~'+cmPerWeek.toFixed(1)+' cm/week | Estimated: '+weeks+' weeks ('+(weeks/4).toFixed(1)+' months). Health threshold for '+g+'s: '+threshold+'cm. Combine caloric deficit + cardio + strength training for best visceral fat reduction.',weeks<26?'green':'yellow');`,
    article:`<h2>Waist Reduction Calculator</h2><p>Waist circumference is one of the strongest predictors of cardiovascular and metabolic health risk — more informative than weight or BMI alone. Excess abdominal fat, particularly visceral fat (around the organs), drives insulin resistance, inflammation, and cardiovascular disease. For men, a waist above 94cm is at-risk; above 102cm is high-risk. For women, at-risk starts at 80cm; high-risk at 88cm.</p>`,
    faqs:[{q:'What is a healthy waist size?',a:'Men: under 94cm is healthy; 94-102cm is at-risk; over 102cm is high-risk. Women: under 80cm is healthy; 80-88cm is at-risk; over 88cm is high-risk.'},{q:'Can I target belly fat specifically?',a:'Spot reduction is a myth — you cannot choose where you lose fat. Cardio and a calorie deficit reduce fat systemically, including from the waist.'},{q:'What type of exercise best reduces waist?',a:'High-intensity cardio (HIIT, running) combined with strength training is most effective for reducing visceral abdominal fat.'},{q:'Why does waist matter more than weight?',a:'Weight does not distinguish fat from muscle. Waist measurement directly reflects abdominal adiposity, which determines metabolic risk.'},{q:'How quickly can waist circumference reduce?',a:'With consistent effort, 1-3 cm per month is realistic. Larger initial waist sizes typically see faster early reductions.'}],
    related:['waist-to-hip-ratio','body-fat-calculator','visceral-fat-calculator','bmi-calculator']
  },

  { slug:'protein-timing-calculator', name:'Protein Timing Calculator', desc:'Optimize when and how to distribute your daily protein intake for maximum muscle synthesis.', icon:'food', category:'Nutrition',
    fields:[{id:'weight',label:'Body Weight (kg)',type:'number',ph:'80'},{id:'goal',label:'Goal',type:'select',options:['Muscle Building','Weight Loss (muscle preservation)','Athletic Performance','General Health']},{id:'meals',label:'Meals Per Day',type:'number',ph:'4'},{id:'training',label:'Training Timing',type:'select',options:['Morning','Midday','Afternoon','Evening']}],
    logic:`var w=parseFloat(document.getElementById('weight').value);var goal=document.getElementById('goal').value;var meals=Math.max(2,Math.min(6,parseFloat(document.getElementById('meals').value)||4));var train=document.getElementById('training').value;if(!w){alert('Enter weight');return;}var mult={'Muscle Building':2.0,'Weight Loss (muscle preservation)':2.2,'Athletic Performance':1.8,'General Health':1.4}[goal]||1.6;var total=Math.round(w*mult);var perMeal=Math.round(total/meals);var prePost=Math.round(total*0.25);showResult('result',total+'g/day','Daily Protein Target','Total: '+total+'g/day ('+mult+'g/kg) distributed over '+meals+' meals = ~'+perMeal+'g each. Around '+train+' training: aim for '+prePost+'g within 2 hours of your workout. Leucine threshold (~2.5-3g per meal) is key for muscle protein synthesis — achieved with ~20-40g protein per meal.',total>0?'green':'yellow');`,
    article:`<h2>Protein Timing Calculator</h2><p>While total daily protein intake is the most important factor for muscle growth and preservation, distribution and timing can provide additional benefits. Muscle protein synthesis (MPS) is maximized when each meal contains sufficient leucine — a branched-chain amino acid that acts as a metabolic trigger for muscle building.</p>`,
    faqs:[{q:'How much protein do I need per day?',a:'For muscle building: 1.6-2.2g per kg body weight. For general health: 0.8-1.2g/kg. For weight loss with muscle preservation: 2.0-2.4g/kg.'},{q:'What is the leucine threshold?',a:'About 2.5-3g of leucine per meal is needed to maximally stimulate muscle protein synthesis. This is found in ~25-40g of most protein sources.'},{q:'Does protein timing around workouts matter?',a:'Moderately. The anabolic window is wider than once thought (several hours). Getting protein within 2 hours post-workout is beneficial.'},{q:'Can I eat too much protein at once?',a:'The body can use and absorb protein from large meals. However, spreading intake across 3-5 meals optimizes MPS stimulus throughout the day.'},{q:'What are complete proteins?',a:'Proteins containing all 9 essential amino acids: animal proteins (meat, fish, dairy, eggs), soy, and quinoa. Combine plant proteins to get all essentials.'}],
    related:['protein-intake-calculator','macro-calculator','macro-timing-calculator','calorie-calculator']
  },

  { slug:'hydration-reminder-calculator', name:'Water Reminder Calculator', desc:'Calculate how often to drink water and set reminders based on your daily target.', icon:'water', category:'Nutrition',
    fields:[{id:'weight',label:'Body Weight (kg)',type:'number',ph:'75'},{id:'wakeup',label:'Wake-Up Time',type:'time'},{id:'bedtime',label:'Bedtime',type:'time'},{id:'container',label:'Container Size (mL)',type:'number',ph:'500'}],
    logic:`var w=parseFloat(document.getElementById('weight').value);var wu=document.getElementById('wakeup').value||'07:00';var bed=document.getElementById('bedtime').value||'23:00';var cont=parseFloat(document.getElementById('container').value)||500;if(!w){alert('Enter weight');return;}var target=Math.round(w*35);var wuh=parseInt(wu.split(':')[0]);var wum=parseInt(wu.split(':')[1])||0;var bedh=parseInt(bed.split(':')[0]);var awakeHours=(bedh-wuh+24)%24;if(awakeHours<8)awakeHours=16;var sips=Math.ceil(target/cont);var intervalMin=Math.round(awakeHours*60/sips);var fmt=function(m){return m>=60?Math.floor(m/60)+'h '+(m%60?m%60+'min':''):m+' min';};showResult('result',target+' mL/day','Hydration Schedule','Daily target: '+target+' mL | Container: '+cont+' mL | Number of refills: '+sips+' | Interval: every '+fmt(intervalMin)+' during '+awakeHours+' awake hours. Tip: drink one glass upon waking, one with each meal, and one before bed — this gets you halfway there!','green');`,
    article:`<h2>Water Reminder Calculator</h2><p>Most people do not drink enough water because they simply forget. Building hydration into your daily schedule with regular reminders is the most effective way to consistently meet your water intake goals. Our calculator breaks your daily target into regular intervals based on your waking hours and preferred container size.</p>`,
    faqs:[{q:'How much water should I drink per day?',a:'A practical guideline is 35mL per kg of body weight (about half your weight in lbs as ounces). Activity and climate increase needs.'},{q:'Is it better to sip water or drink large amounts?',a:'Sipping regularly throughout the day is more effective — the kidneys can only process about 800mL per hour.'},{q:'Does sparkling water hydrate as well as still?',a:'Yes. Sparkling water hydrates just as effectively as still water. Its slight acidity is negligible with normal intake.'},{q:'Can I drink too much water?',a:'Hyponatremia (water intoxication) is rare outside extreme endurance events. Thirst is generally a reliable guide for most people.'},{q:'Does cold vs warm water matter?',a:'Cold water is absorbed slightly faster; warm water may aid digestion. The difference is minimal — drink at your preferred temperature.'}],
    related:['water-intake-calculator','hydration-level-calculator','electrolyte-calculator','calorie-calculator']
  },

  { slug:'body-recomposition-calculator', name:'Body Recomposition Calculator', desc:'Calculate calories and macros for simultaneous fat loss and muscle gain (body recomposition).', icon:'body', category:'Body Metrics',
    fields:[{id:'weight',label:'Body Weight (kg)',type:'number',ph:'85'},{id:'height',label:'Height (cm)',type:'number',ph:'175'},{id:'age',label:'Age',type:'number',ph:'30'},{id:'gender',label:'Gender',type:'select',options:['Male','Female']},{id:'activity',label:'Activity Level',type:'select',options:['Sedentary','Lightly Active','Moderately Active','Very Active']},{id:'bodyfat',label:'Current Body Fat (%)',type:'number',ph:'25'}],
    logic:`var w=parseFloat(document.getElementById('weight').value);var h=parseFloat(document.getElementById('height').value);var a=parseFloat(document.getElementById('age').value);var g=document.getElementById('gender').value;var act=document.getElementById('activity').value;var bf=parseFloat(document.getElementById('bodyfat').value)||20;if(!w||!h||!a){alert('Fill all fields');return;}var bmr=g==='Male'?10*w+6.25*h-5*a+5:10*w+6.25*h-5*a-161;var m={'Sedentary':1.2,'Lightly Active':1.375,'Moderately Active':1.55,'Very Active':1.725};var tdee=Math.round(bmr*(m[act]||1.375));var recompCal=Math.round(tdee*0.95);var protein=Math.round(w*2.2);var fat=Math.round(w*0.8);var carbCal=recompCal-protein*4-fat*9;var carbs=Math.max(50,Math.round(carbCal/4));showResult('result',recompCal+' kcal','Body Recomposition Targets','TDEE: '+tdee+' kcal → Recomp: '+recompCal+' kcal (5% deficit) | Protein: '+protein+'g | Fat: '+fat+'g | Carbs: '+carbs+'g. Training: 3-4x strength + 2-3x cardio/week. Expect slow progress (1-2 lbs fat loss/month) but simultaneous muscle gain. Best for beginners and those returning to training.','green');`,
    article:`<h2>Body Recomposition Calculator</h2><p>Body recomposition — simultaneously losing fat and gaining muscle — is the holy grail of fitness transformation. Once thought impossible, research confirms it is achievable, particularly for beginners, those returning to training after a break, those with higher body fat percentages, and (with proper protocols) experienced athletes.</p>`,
    faqs:[{q:'Can you lose fat and gain muscle at the same time?',a:'Yes, especially for beginners, those returning to training, and those with higher body fat percentages. It requires a slight deficit, high protein, and progressive training.'},{q:'How long does body recomposition take?',a:'Visible results typically take 3-6 months. The process is slower than dedicated bulking or cutting but maintains better body composition throughout.'},{q:'What is the key to successful recomposition?',a:'High protein intake (2.0-2.4g/kg), slight calorie deficit (5-15%), progressive resistance training, and adequate sleep.'},{q:'Who is best suited for recomposition?',a:'Beginners, those returning after breaks, and those with significant body fat to lose benefit most. Advanced lean athletes may need to choose bulking or cutting.'},{q:'What is "newbie gains"?',a:'The phenomenon where beginners can simultaneously build significant muscle and lose fat in the first 6-12 months of training due to high training sensitivity.'}],
    related:['body-fat-calculator','lean-mass-goal-calculator','calorie-calculator','protein-timing-calculator']
  },

];
